function isHypotheticalTheme(session){return session?.symbolicFrame==='hypothetical' || /(brujer[ií]a|mal de ojo|energ[ií]a externa|influencia externa|hechizo|carga externa|ambiente pesado)/i.test(session?.topic||'')}
