const SecureStore = {
  b64(bytes){return btoa(String.fromCharCode(...new Uint8Array(bytes)))},
  unb64(s){const bin=atob(s);const a=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)a[i]=bin.charCodeAt(i);return a},
  async derive(pin,salt){
    const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveKey']);
    return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:180000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},true,['encrypt','decrypt']);
  },
  async importSessionKey(){
    const raw=sessionStorage.getItem(KEYS.key);if(!raw)return null;
    return crypto.subtle.importKey('raw',this.unb64(raw),{name:'AES-GCM'},true,['encrypt','decrypt']);
  },
  async rememberKey(key){const raw=await crypto.subtle.exportKey('raw',key);sessionStorage.setItem(KEYS.key,this.b64(raw))},
  async encryptObj(obj,key){const iv=crypto.getRandomValues(new Uint8Array(12));const enc=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(JSON.stringify(obj)));return {encrypted:true,iv:this.b64(iv),data:this.b64(enc)}},
  async decryptObj(pack,key){const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:this.unb64(pack.iv)},key,this.unb64(pack.data));return JSON.parse(new TextDecoder().decode(plain))},
  async load(){
    state.settings={...DEFAULT_SETTINGS,...JSON.parse(localStorage.getItem(KEYS.settings)||'{}')};state.settings.visualWorld=normalizeVisualWorldKey(state.settings.visualWorld);
    const raw=localStorage.getItem(KEYS.data); if(!raw){state.data={active:null,sessions:[]};return}
    const pack=JSON.parse(raw);
    if(pack.encrypted){const key=await this.importSessionKey();if(!key){state.locked=true;return}try{state.data=await this.decryptObj(pack,key)}catch{state.locked=true;sessionStorage.removeItem(KEYS.key)}}
    else state.data=pack;
  },
  saveSettings(){localStorage.setItem(KEYS.settings,JSON.stringify(state.settings))},
  async saveData(){
    const meta=JSON.parse(localStorage.getItem(KEYS.lock)||'null');
    if(meta){const key=await this.importSessionKey();if(!key){state.locked=true;return}localStorage.setItem(KEYS.data,JSON.stringify(await this.encryptObj(state.data,key)))}
    else localStorage.setItem(KEYS.data,JSON.stringify(state.data));
  },
  async setupPin(pin){
    const salt=crypto.getRandomValues(new Uint8Array(16));const key=await this.derive(pin,salt);const iv=crypto.getRandomValues(new Uint8Array(12));
    const verifier=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode('mi-campo-ok'));
    localStorage.setItem(KEYS.lock,JSON.stringify({salt:this.b64(salt),iv:this.b64(iv),verifier:this.b64(verifier)}));
    await this.rememberKey(key);state.locked=false;await this.saveData();
  },
  async unlock(pin){
    const meta=JSON.parse(localStorage.getItem(KEYS.lock)||'null');if(!meta)return true;
    try{const key=await this.derive(pin,this.unb64(meta.salt));const check=await crypto.subtle.decrypt({name:'AES-GCM',iv:this.unb64(meta.iv)},key,this.unb64(meta.verifier));if(new TextDecoder().decode(check)!=='mi-campo-ok')throw new Error();await this.rememberKey(key);state.locked=false;state.unlockError='';await this.load();return true}catch{state.unlockError='El código no coincide.';return false}
  },
  async disablePin(){
    const key=await this.importSessionKey();const raw=JSON.parse(localStorage.getItem(KEYS.data)||'{}');if(raw.encrypted&&key)state.data=await this.decryptObj(raw,key);
    localStorage.removeItem(KEYS.lock);sessionStorage.removeItem(KEYS.key);localStorage.setItem(KEYS.data,JSON.stringify(state.data));state.locked=false;
  },
  lockedEnabled(){return !!localStorage.getItem(KEYS.lock)},
  clearAll(){Object.values(KEYS).forEach(k=>{localStorage.removeItem(k);sessionStorage.removeItem(k)});state.data={active:null,sessions:[]};state.settings={...DEFAULT_SETTINGS};}
};

const PhotoDB = {
  db:null,
  open(){return new Promise((resolve,reject)=>{const r=indexedDB.open('mi-campo-media',1);r.onupgradeneeded=()=>r.result.createObjectStore('photos');r.onsuccess=()=>{this.db=r.result;resolve(r.result)};r.onerror=()=>reject(r.error)})},
  async put(id,file){const db=this.db||await this.open();return new Promise((resolve,reject)=>{const tx=db.transaction('photos','readwrite');tx.objectStore('photos').put(file,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})},
  async get(id){if(!id)return null;const db=this.db||await this.open();return new Promise((resolve,reject)=>{const r=db.transaction('photos').objectStore('photos').get(id);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)})},
  async clear(){const db=this.db||await this.open();return new Promise((resolve,reject)=>{const tx=db.transaction('photos','readwrite');tx.objectStore('photos').clear();tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
};

class FacilitatorProvider { async suggest(){return null} }
class LocalFacilitator extends FacilitatorProvider {
  async suggest(ctx){
    if(ctx.kind==='intention') return buildIntention(ctx.topic);
    if(ctx.kind==='phrase') return choosePhrase(ctx.session);
    return null;
  }
}
const facilitator = new LocalFacilitator();

function buildIntention(topic){const t=(topic||'este tema').trim();return `Quiero observar simbólicamente ${t.charAt(0).toLowerCase()+t.slice(1)} y notar qué posición, distancia o siguiente paso me resulta más equilibrado, sin buscar una explicación definitiva.`}
function choosePhrase(session){
  const custom=session?.exerciseProtocol?.phrases;
  if(Array.isArray(custom)&&custom.length)return custom[state.phraseIndex % custom.length];
  const presetCat=session?.exerciseProtocol?.phraseCategory;
  const cat=presetCat&&PHRASES[presetCat]?presetCat:(session.type==='decision'?'decisions':session.type==='family'?'parents':session.type==='relationship'?'couple':session.type==='project'?'resources':session.type==='individual'?'autonomy':'resources');
  return PHRASES[cat][state.phraseIndex % PHRASES[cat].length];
}
function detectCrisis(text){return /(suicid|matarme|quitarme la vida|hacerme daño|autoles|no quiero vivir|peligro inmediato|voy a lastimarme)/i.test(text||'')}
function detectOverwhelm(text){return /(p[aá]nico|muy angustiad|desbordad|no puedo respirar|demasiado intenso|muy mal)/i.test(text||'')}

function createSession(){return {
  id:uid('session'),createdAt:nowISO(),updatedAt:nowISO(),status:'active',template:null,type:'free',topic:'',intention:'',depth:state.settings.depth,duration:'10',pieceCount:'4-6',openingStyle:state.settings.opening,facilitatorStyle:state.settings.facilitator,
  familyStructure:'unspecified',familyUnknownMode:false,intuitionPrompt:'',symbolicFrame:'symbolic',specialPreset:null,stage:'setup',pieces:[],placementIndex:0,initialLayout:null,currentLayout:null,layoutHistory:[],movements:[],responses:[],phrasesTested:[],symbolicReadings:[],reflection:'',integration:{activity:'',action:''},photos:{initial:null,final:null},notes:[],closing:{completed:false},
  visualWorld:state.settings.visualWorld||'ocean',motionStyle:state.settings.motionStyle||'tide',soundscape:state.settings.ambientScene||'water',voiceRole:'guide',timelineEnabled:true,
  exerciseId:null,exerciseCategory:null,exerciseProtocol:null
}}
function piece(label,i){return {id:uid('piece'),label,role:label,x:.18+(i%3)*.31,y:.23+Math.floor(i/3)*.34,rotation:0,posture:'upright',placed:false,source:'selected',hypothetical:false}}
function intuitivePiece(label,i){const p=piece(label,i);p.source='intuition';p.hypothetical=true;return p}
function shouldMarkIntuitiveLabel(label){return /(desconoc|siento que falta|simb[oó]lic|imaginad|vac[ií]o|ancestr|algo no conocido|ausencia que siento|rama familiar que siento|no s[eé] nombrar|sensaci[oó]n|parte de m[ií]|miedo sin nombre|energ[ií]a|presencia interna|influencia energ[eé]tica|recurso interno|recurso energ[eé]tico)/i.test(label||'')}
function layoutSnapshot(session){return session.pieces.filter(p=>p.placed).map(p=>({id:p.id,x:+p.x.toFixed(4),y:+p.y.toFixed(4),rotation:p.rotation,posture:p.posture||'upright',label:p.label}))}
function applySnapshot(session,snap){snap.forEach(s=>{const p=session.pieces.find(x=>x.id===s.id);if(p){p.x=s.x;p.y=s.y;p.rotation=s.rotation;p.posture=s.posture||'upright';p.placed=true}})}
async function persist(){if(state.data.active)state.data.active.updatedAt=nowISO();await SecureStore.saveData()}
function haptic(){if(state.settings.vibration && navigator.vibrate)navigator.vibrate(18)}
function toast(msg){state.toast=msg;render();setTimeout(()=>{if(state.toast===msg){state.toast=null;render()}},1800)}

function normalizeData(){
  if(!state.data||typeof state.data!=='object')state.data={active:null,sessions:[]};
  if(!Array.isArray(state.data.sessions))state.data.sessions=[];
  if(!state.data.genogram)state.data.genogram={nodes:[{id:'geno_self',label:'Yo',relation:'Yo',branch:'self',generation:0}]};
  if(!Array.isArray(state.data.genogram.nodes))state.data.genogram.nodes=[];
  if(!state.data.memory)state.data.memory={events:[]};
  if(!Array.isArray(state.data.memory.events))state.data.memory.events=[];
  if(!Array.isArray(state.data.customPractices))state.data.customPractices=[];
  if(!Array.isArray(state.data.generatedPlans))state.data.generatedPlans=[];
  if(!state.data.lab)state.data.lab=createLabState();
}
function createLabState(){return {id:'lab',type:'free',topic:'Laboratorio del Campo',symbolicFrame:'symbolic',familyUnknownMode:false,pieces:[piece('Yo',0),piece('Tema',1),piece('Recurso',2)].map((p,i)=>({...p,placed:true,x:.24+i*.26,y:.5})),initialLayout:null,currentLayout:null,layoutHistory:[],movements:[],responses:[],symbolicReadings:[]}}
function memoryEvent(kind,payload={}){if(!state.settings.memoryEnabled)return;normalizeData();state.data.memory.events.push({id:uid('mem'),at:nowISO(),kind,...payload});if(state.data.memory.events.length>240)state.data.memory.events=state.data.memory.events.slice(-240);persist()}
function memoryInsights(){normalizeData();const sessions=state.data.sessions||[];const events=state.data.memory.events||[];if(!sessions.length&&!events.length)return [];
  const types={};const reps={};sessions.slice(0,20).forEach(s=>{types[s.type]=(types[s.type]||0)+1;(s.pieces||[]).forEach(p=>reps[p.label]=(reps[p.label]||0)+1)});
  const topType=Object.entries(types).sort((a,b)=>b[1]-a[1])[0];const topRep=Object.entries(reps).filter(([k])=>!/^(yo|recurso)$/i.test(k)).sort((a,b)=>b[1]-a[1])[0];const dismissed=events.filter(e=>e.kind==='reading-dismissed').slice(-10);
  const out=[];if(topType)out.push(`Has explorado con más frecuencia la modalidad ${TYPE_DEFS[topType[0]]?.label||topType[0]}.`);if(topRep)out.push(`Una figura que se repite en tus sesiones es “${topRep[0]}”.`);if(dismissed.length>=2)out.push('Campo recuerda las lecturas que descartas para favorecer variaciones y evitar insistir.');return out.slice(0,3)
}
function availableVoices(){if(!('speechSynthesis'in window))return [];return window.speechSynthesis.getVoices().filter(v=>/^es(?:-|_)/i.test(v.lang)||/Spanish|Español/i.test(v.name))}
function voiceOptions(selected){const vs=availableVoices();if(!vs.length)return `<option value="">Voz española disponible del sistema</option>`;return [`<option value="">Automática</option>`,...vs.map(v=>`<option value="${esc(v.voiceURI)}" ${v.voiceURI===selected?'selected':''}>${esc(v.name)} · ${esc(v.lang)}</option>`)].join('')}
function chooseVoice(role='guide'){const target=role==='companion'?state.settings.companionVoiceURI:state.settings.voiceURI;const voices=availableVoices();return voices.find(v=>v.voiceURI===target)||voices.find(v=>/Mexico|MX/i.test(v.name+' '+v.lang))||voices[0]||null}
function soundscapeLabel(v){return ({silence:'Silencio',cosmic:'Cósmico',aurora:'Aurora luminosa',water:'Agua astral',forest:'Bosque vivo',solar:'Solar cálido',lunar:'Lunar profundo',deep:'Profundo',storm:'Tormenta estelar'}[v]||v)}
function sessionVoiceRole(){const s=state.data.active;return s?.voiceRole||'guide'}
function speak(text,role='guide'){if(!text||!state.settings.speech||!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='es-MX';const v=chooseVoice(role);if(v)u.voice=v;u.rate=state.settings.instructionSpeed==='slow'?.82:state.settings.instructionSpeed==='fast'?1.12:.96;u.pitch=role==='companion'?1.08:1;u.volume=1;window.speechSynthesis.speak(u)}
function stopSpeak(){if('speechSynthesis'in window)window.speechSynthesis.cancel()}

function shell(content,{nav=true,pause=false,title='Campo'}={}){
  const home=state.route==='home';
  return `<div class="app-shell ${home?'home-shell target-home-shell':''}">
    ${home?`<header class="home-floating-actions" aria-label="Accesos rápidos"><button class="home-round-action profile-action" aria-label="Abrir perfil y ajustes" onclick="MiCampo.go('settings')">${homeGlyph('profile')}</button><button class="home-round-action bell-action" aria-label="Abrir novedades" onclick="MiCampo.openNotifications()">${homeGlyph('bell')}<i></i></button></header>`:`<header class="topbar"><div class="brand"><div class="brand-mark">${iconMark()}</div><span>${esc(title)}</span></div><div class="top-actions"><button class="icon-btn theme-toggle" aria-label="Cambiar apariencia" title="Cambiar apariencia" onclick="MiCampo.toggleTheme()">${state.settings.theme==='dark'?'☀':'☾'}</button><button class="icon-btn settings-shortcut" aria-label="Abrir ajustes" title="Ajustes" onclick="MiCampo.go('settings')">⚙︎</button></div></header>`}
    <main class="content">${content}</main>
    ${pause?`<button class="pause-fab" aria-label="Pausar sesión" onclick="MiCampo.pause()">Ⅱ</button>`:''}
    ${nav?bottomNav():''}
    ${state.toast?`<div class="toast">${esc(state.toast)}</div>`:''}
    ${state.modal?renderModal():''}
  </div>`
}
function bottomNav(){return `<nav class="bottom-nav cosmic-bottom-nav" aria-label="Navegación principal">
  ${navBtn('home','🏠','Inicio','nav-home')}
  <button class="nav-btn nav-explore ${state.route==='new'?'active':''}" onclick="MiCampo.startNew()"><span>✨</span><span>Explorar</span></button>
  ${navBtn('library','🪷','Prácticas','nav-practices')}
  ${navBtn('history','📔','Diario','nav-journal')}
  <button class="nav-btn nav-breathe" onclick="MiCampo.quickBreath()"><span>🌙</span><span>Respirar</span></button>
</nav>`}
function navBtn(route,ico,label,extra=''){return `<button class="nav-btn ${extra} ${state.route===route?'active':''}" onclick="MiCampo.go('${route}')"><span>${ico}</span><span>${label}</span></button>`}
function progress(label,step,total){const pct=Math.max(4,Math.min(100,step/total*100));return `<div class="progress-wrap"><div class="progress-meta"><span>${esc(label)}</span><span>${step} de ${total}</span></div><div class="progress"><span style="width:${pct}%"></span></div></div>`}
function safetyNote(){return ''}

function homeView(){
  const active=state.data.active;
  const continueAction=active?`onclick="MiCampo.resume()"`:`onclick="MiCampo.go('history')"`;
  const continueSub=active?'Última sesión abierta':'Sesiones guardadas';
  const worldKey=normalizeVisualWorldKey(state.settings.visualWorld);
  return shell(`<section class="cosmic-home premium-home design-home-target world-layout-${worldKey}">
    <div class="home-stars" aria-hidden="true"></div>
    ${worldEnvironment()}
    <button class="cosmic-title premium-title target-title" onclick="MiCampo.openWorlds()" aria-label="CAMPO. Cambiar universo visual"><span class="title-flare" aria-hidden="true">✦</span><h1>CAMPO</h1><div class="eyebrow">EXPLORACIÓN SIMBÓLICA GUIADA</div></button>
    <div class="radial-scene premium-radial target-radial">
      <div class="radial-ring ring-a"></div><div class="radial-ring ring-b"></div><div class="radial-ring ring-c"></div>
      <div class="target-orbit-lines" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div>
      ${state.settings.companion?`<div class="axoflutter-stage target-axoflutter"><div class="axoflutter-aura" aria-hidden="true"></div><button class="companion-touch premium-companion" onclick="MiCampo.companionPanel()" aria-label="Abrir a Axoflutter, tu Compañero de Campo"><div id="companion3d-home" class="companion3d">${companionFallbackMarkup('home')}</div></button></div>`:''}
      <button class="radial-core premium-core target-core" onclick="MiCampo.startNew()" aria-label="Iniciar una nueva constelación"><span class="core-star">${homeGlyph('star')}</span><strong>INICIAR<br>CONSTELACIÓN</strong><small>Nueva exploración<br>guiada</small></button>
      <button class="orbit-node orbit-history premium-node node-gold target-node" onclick="MiCampo.go('history')"><span class="orbit-icon">${homeGlyph('history')}</span><strong>HISTORIAL</strong><small>Sesiones<br>guardadas</small></button>
      <button class="orbit-node orbit-continue premium-node node-cyan target-node" ${continueAction}><span class="orbit-icon">${homeGlyph('continue')}</span><strong>CONTINUAR</strong><small>${esc(continueSub)}</small></button>
      <button class="orbit-node orbit-settings premium-node node-amber target-node" onclick="MiCampo.go('settings')"><span class="orbit-icon">${homeGlyph('settings')}</span><strong>AJUSTES</strong><small>Voz, estilo,<br>privacidad y<br>experiencia</small></button>
      <button class="orbit-node orbit-library premium-node node-blue target-node" onclick="MiCampo.go('library')"><span class="orbit-icon">${homeGlyph('library')}</span><strong>BIBLIOTECA</strong><small>Recursos,<br>guías y más</small></button>
      <button class="orbit-node orbit-modalities premium-node node-pink target-node" onclick="MiCampo.startNew()"><span class="orbit-icon">${homeGlyph('modalities')}</span><strong>MODALIDADES</strong><small>Familiar, relaciones,<br>decisiones y más</small></button>
    </div>
    <section class="living-guide-card target-guide-card">
      <button class="guide-avatar target-guide-avatar" onclick="MiCampo.companionPanel()" aria-label="Abrir Guía Viva"><img src="./assets/character/axoflutter_reference.jpg" alt="Axoflutter, Compañero de Campo"><span class="guide-heart">◇</span></button>
      <div class="guide-copy"><div class="guide-heading"><span>✦</span><strong>GUÍA VIVA</strong><span>✦</span></div><h3>¡Hola, soy tu Compañero de Campo!</h3><p>${active?'Tu constelación sigue abierta. Puedo acompañarte con voz, movimiento, ambiente e interpretación simbólica.':'Estoy aquí para acompañarte en cada exploración. Cuando estés list@, podemos iniciar una nueva constelación juntos.'}</p><button class="guide-connect" onclick="MiCampo.companionPanel()">Conectar con mi guía <span>✧</span></button></div>
    </section>
  </section>`)
}

function stageLabel(stage){return ({setup:'Configuración',opening:'Apertura',placement:'Colocación',observation:'Observación',movement:'Movimiento',phrase:'Frase simbólica',closing:'Cierre',integration:'Integración'}[stage]||stage)}

function newView(){
  switch(state.wizardStep){
    case 'type': return typeStep();case 'family':return familyStep();case 'individual':return individualStep();case 'energetic':return energeticStep();case 'template':return templateStep();case 'topic':return topicStep();case 'intention':return intentionStep();case 'depth':return depthStep();case 'duration':return durationStep();case 'pieces':return piecesStep();case 'prepare':return prepareStep();case 'reps':return repsStep();default:return typeStep();
  }
}
function wizardShell(inner,step,total=8){return shell(`${progress('Preparación',step,total)}${inner}`,{nav:false,title:'Nueva constelación'})}
function typeStep(){return wizardShell(`<section class="hero"><div class="eyebrow">Paso 1</div><h2>¿Qué quieres explorar?</h2><p class="lead">Elige una modalidad para organizar la experiencia.</p></section><div class="grid modality-grid">${Object.entries(TYPE_DEFS).map(([k,v])=>`<button class="choice modality-card" onclick="MiCampo.chooseType('${k}')"><span class="choice-icon">${v.icon}</span><span><strong>${v.label}</strong><small>${v.desc}</small></span></button>`).join('')}</div><div class="action-stack"><button class="btn secondary wide" onclick="MiCampo.go('builder')">＋ Constructor personalizado</button><button class="btn ghost wide" onclick="MiCampo.wizard('template')">Usar una plantilla</button></div>`,1)}
function specialPresetCards(list,kind){return `<div class="special-topic-grid">${list.map(x=>`<button class="special-topic ${x.frame==='hypothetical'?'hypothetical':''}" onclick="MiCampo.specialPreset('${kind}','${x.id}')"><span class="special-icon">${x.icon}</span><span><strong>${esc(x.title)}</strong><small>${esc(x.desc)}</small>${x.frame==='hypothetical'?`<em>Hipótesis simbólica</em>`:''}</span></button>`).join('')}</div>`}
function familyStep(){const s=ensureActive();const structures=[['adoptive','Familia adoptiva','Vínculos adoptivos y de crianza'],['origin','Familia de origen','Familia biológica o de origen'],['both','Ambas','Adoptiva y de origen'],['intuitive','Orígenes desconocidos · intuitivo','Crea figuras simbólicas para lo que no conoces'],['chosen','Familia elegida','Personas que tú consideras familia'],['manual','Construir manualmente','Sin estructura predeterminada'],['unspecified','No definirlo','Puedes decidir después']];return wizardShell(`<section class="hero"><div class="eyebrow">Familiar</div><h2>¿Cómo quieres representar tu familia?</h2><p class="lead">Puedes trabajar con datos conocidos o dejar que tu intuición cree figuras hipotéticas para los espacios que no conoces.</p></section><div class="grid two">${structures.map(x=>`<button class="choice ${s.familyStructure===x[0]?'selected':''}" onclick="MiCampo.setFamilyStructure('${x[0]}')"><span><strong>${x[1]}</strong><small>${x[2]}</small></span></button>`).join('')}</div><section class="intuition-entry"><div class="card intuition-card"><div class="eyebrow">Modo intuitivo</div><h3>¿No conoces tu familia biológica o la historia de tus ancestros?</h3><p class="note">Campo puede ayudarte a crear personajes simbólicos para una presencia, ausencia, rama o cualidad que sientas. Tú decides por intuición qué entra, cómo se llama y cuándo descartarlo.</p><button class="btn secondary wide" onclick="MiCampo.familyIntuitiveStart()">✦ Explorar los vacíos por intuición</button></div></section><section><div class="section-title"><h3>Comienzos rápidos</h3></div><div class="family-presets">${FAMILY_PRESETS.map(x=>`<button class="family-preset" onclick="MiCampo.familyPreset('${x.id}')"><span>${x.intuitive?'◌':'✧'}</span><strong>${x.title}</strong></button>`).join('')}</div></section><section class="special-topic-section"><div class="section-title"><div><div class="eyebrow">Temas específicos</div><h3>Adicciones y exploraciones hipotéticas</h3></div></div>${specialPresetCards(FAMILY_SYMBOLIC_PRESETS,'family')}</section><div class="action-stack"><button class="btn secondary wide" onclick="MiCampo.familyManual()">Construir mi propia selección</button><button class="btn ghost wide" onclick="MiCampo.wizard('type')">Atrás</button></div>`,1,9)}
function individualStep(){return wizardShell(`<section class="hero"><div class="eyebrow">Individual</div><h2>¿Qué quieres mirar dentro de tu experiencia?</h2><p class="lead">Puedes trabajar con temas preparados o dejar que la intuición dé forma a partes internas, vacíos y sensaciones difíciles de nombrar.</p></section><section class="intuition-entry"><div class="card intuition-card"><div class="eyebrow">Modo intuitivo</div><h3>¿Quieres explorar desde lo que sientes, aunque no sepas explicarlo del todo?</h3><p class="note">Campo puede crear figuras hipotéticas para partes de ti, sensaciones internas, recursos o vacíos. Tú eliges por intuición qué entra, cómo se llama y cuándo descartarlo.</p><button class="btn secondary wide" onclick="MiCampo.individualIntuitiveStart()">✦ Explorar lo interno por intuición</button></div></section><section><div class="section-title"><h3>Exploraciones individuales</h3></div>${specialPresetCards(INDIVIDUAL_PRESETS,'individual')}</section><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.individualManual()">Tema individual libre</button><button class="btn ghost wide" onclick="MiCampo.wizard('type')">Atrás</button></div>`,1,9)}
function energeticStep(){return wizardShell(`<section class="hero"><div class="eyebrow">Energética</div><h2>¿Qué quieres observar dentro de tu campo energético?</h2><p class="lead">Puedes trabajar con sensaciones, cargas, protecciones o influencias percibidas sin perder el carácter simbólico e hipotético.</p></section><section class="intuition-entry"><div class="card intuition-card"><div class="eyebrow">Modo intuitivo</div><h3>¿Quieres dejar que energías o presencias tomen forma por intuición?</h3><p class="note">Campo puede ayudarte a crear figuras simbólicas para cargas, protecciones, presencias o influencias que sientas sin necesidad de nombrarlas con precisión.</p><button class="btn secondary wide" onclick="MiCampo.energeticIntuitiveStart()">✦ Explorar lo energético por intuición</button></div></section><section><div class="section-title"><h3>Exploraciones energéticas</h3></div>${specialPresetCards(ENERGETIC_PRESETS,'energetic')}</section><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.energeticManual()">Tema energético libre</button><button class="btn ghost wide" onclick="MiCampo.wizard('type')">Atrás</button></div>`,1,9)}
function templateStep(){return wizardShell(`<section class="hero"><div class="eyebrow">Plantillas</div><h2>Empieza desde una estructura editable.</h2></section><div class="list">${TEMPLATES.map((t,i)=>`<button class="choice" onclick="MiCampo.chooseTemplate(${i})"><span class="choice-icon">${TYPE_DEFS[t[1]].icon}</span><span><strong>${esc(t[0])}</strong><small>${t[2].join(' · ')}</small></span></button>`).join('')}</div><button class="btn ghost wide" onclick="MiCampo.wizard('type')">Volver a modalidades</button>`,1)}
function previousSetupStep(type){return type==='family'?'family':type==='individual'?'individual':type==='energetic'?'energetic':'type'}
function topicStep(){const s=ensureActive();const modeNote=isHypotheticalTheme(s)?`<div class="mode-note hypothetical-mode"><span>✧</span><div><strong>Modo hipotético</strong><small>Campo puede desarrollar esta narrativa como posibilidad simbólica y traducir posiciones, posturas y movimientos sin presentarla como una comprobación externa.</small></div></div>`:isAddictionTheme(s)?`<div class="mode-note wellbeing-mode"><span>◍</span><div><strong>Exploración de adicción / compulsión</strong><small>El campo se centrará en impulso, necesidades, consecuencias, límites, apoyos y recursos.</small></div></div>`:'';return wizardShell(`<section class="hero"><div class="eyebrow">Paso 2</div><h2>¿Qué tema quieres explorar?</h2><p class="lead">Describe brevemente la situación que quieres representar.</p></section>${modeNote}<div class="field"><label for="topic">Tema</label><textarea id="topic" maxlength="700" placeholder="Ej. Quiero observar qué me pasa con este tema…" oninput="MiCampo.setField('topic',this.value)">${esc(s.topic)}</textarea></div><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.topicNext()">Continuar</button><button class="btn ghost wide" onclick="MiCampo.wizard('${previousSetupStep(s.type)}')">Atrás</button></div>`,2)}
function intentionStep(){const s=ensureActive();return wizardShell(`<section class="hero"><div class="eyebrow">Paso 3</div><h2>Convirtamos el tema en una intención.</h2><p class="lead">La intención describe qué quieres observar durante la sesión.</p></section><div class="field"><label for="intention">Intención breve</label><textarea id="intention" maxlength="900" oninput="MiCampo.setField('intention',this.value)">${esc(s.intention)}</textarea></div><div class="card soft"><strong>Enfoque</strong><p class="note">Puedes usar verbos como observar, notar, explorar o comprender para mantener la intención abierta.</p></div><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.wizard('depth')">Usar esta intención</button><button class="btn ghost wide" onclick="MiCampo.wizard('topic')">Atrás</button></div>`,3)}
function depthStep(){const s=ensureActive();return wizardShell(`<section class="hero"><div class="eyebrow">Paso 4</div><h2>Profundidad</h2><p class="lead">Esto cambia la cantidad de preguntas, pausas y profundidad de la lectura simbólica.</p></section><div class="grid">${[['soft','Suave','Menos preguntas y movimientos.'],['normal','Normal','Equilibrio entre observación y experimentos.'],['deep','Profunda','Más pausas y preguntas, siempre opcionales.']].map(x=>choiceSelect('depth',x[0],x[1],x[2],s.depth)).join('')}</div><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.wizard('duration')">Continuar</button><button class="btn ghost wide" onclick="MiCampo.wizard('intention')">Atrás</button></div>`,4)}
function durationStep(){const s=ensureActive();return wizardShell(`<section class="hero"><div class="eyebrow">Paso 5</div><h2>Duración aproximada</h2></section><div class="grid two">${['5','10','20','30','Sin límite'].map(v=>`<button class="choice ${s.duration===v?'selected':''}" onclick="MiCampo.setSessionChoice('duration','${v}')"><span><strong>${v==='Sin límite'?v:v+' min'}</strong><small>Puedes cerrar antes cuando quieras.</small></span></button>`).join('')}</div><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.wizard('pieces')">Continuar</button><button class="btn ghost wide" onclick="MiCampo.wizard('depth')">Atrás</button></div>`,5)}
function piecesStep(){const s=ensureActive();return wizardShell(`<section class="hero"><div class="eyebrow">Paso 6</div><h2>Número de piezas</h2><p class="lead">La primera plantilla de prueba usa cuatro. Puedes editar los representantes antes de comenzar.</p></section><div class="grid">${[['2-3','2–3','Muy simple'],['4-6','4–6','Recomendado'],['7-10','7–10','Campo amplio'],['auto','Automático','Según modalidad']].map(x=>choiceSelect('pieceCount',x[0],x[1],x[2],s.pieceCount)).join('')}</div><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.wizard('prepare')">Continuar</button><button class="btn ghost wide" onclick="MiCampo.wizard('duration')">Atrás</button></div>`,6)}
function choiceSelect(field,val,title,desc,current){return `<button class="choice ${current===val?'selected':''}" onclick="MiCampo.setSessionChoice('${field}','${val}')"><span><strong>${title}</strong><small>${desc}</small></span></button>`}
function sessionWorldOptions(s){return Object.entries(VISUAL_WORLDS).map(([k,w])=>`<option value="${k}" ${(s.visualWorld||state.settings.visualWorld)===k?'selected':''}>${w.icon} ${w.label}</option>`).join('')}
function sessionMotionOptions(s){return Object.entries(MOTION_STYLES).map(([k,m])=>`<option value="${k}" ${(s.motionStyle||state.settings.motionStyle)===k?'selected':''}>${m.icon} ${m.label}</option>`).join('')}
function prepareStep(){const s=ensureActive();return wizardShell(`<section class="hero"><div class="eyebrow">Paso 7</div><h2>Prepara el espacio.</h2><p class="lead">Ten tus piezas a la mano y deja suficiente lugar para moverlas.</p></section><div class="card"><div class="list"><div><strong>1 · Mesa despejada</strong><p class="note">Deja espacio para colocar y mover las piezas con comodidad.</p></div><div><strong>2 · Piezas al alcance</strong><p class="note">Puedes elegirlas una a una durante la sesión.</p></div><div><strong>3 · Ritmo propio</strong><p class="note">Puedes pausar o cerrar cuando quieras.</p></div></div></div><div class="field"><label>¿Cómo quieres que Campo te acompañe?</label><div class="opening-grid">${Object.entries(OPENING_STYLES).map(([v,o])=>`<button class="opening-card ${s.openingStyle===v?'selected':''}" onclick="MiCampo.setSessionChoice('openingStyle','${v}')"><span>${o.icon}</span><strong>${o.label}</strong><small>${o.desc}</small></button>`).join('')}</div></div><section class="card session-audio-card"><div class="eyebrow">Mundo, voz y ambiente de esta constelación</div><div class="session-world-row"><div class="field compact"><label>Mundo visual</label><select onchange="MiCampo.setSessionWorld(this.value)">${sessionWorldOptions(s)}</select></div><div class="field compact"><label>Movimiento</label><select onchange="MiCampo.setSessionMotion(this.value)">${sessionMotionOptions(s)}</select></div></div><div class="field compact"><label>Quién narra</label><select onchange="MiCampo.setSessionChoice('voiceRole',this.value)"><option value="guide" ${s.voiceRole==='guide'?'selected':''}>Guía de Campo</option><option value="companion" ${s.voiceRole==='companion'?'selected':''}>Axoflutter · acompañante</option><option value="silent" ${s.voiceRole==='silent'?'selected':''}>Sin voz</option></select></div><div class="field compact"><label>Paisaje sonoro</label><select onchange="MiCampo.setSessionSoundscape(this.value)">${['silence','water','forest','storm','deep'].map(v=>`<option value="${v}" ${s.soundscape===v?'selected':''}>${soundscapeLabel(v)}</option>`).join('')}</select></div><div class="secondary-actions"><button class="btn ghost" onclick="MiCampo.previewSessionVoice()">🔊 Probar voz</button><button class="btn ghost" onclick="MiCampo.previewSoundscape()">♫ Probar ambiente</button></div></section><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.prepareReps()">Elegir representantes</button><button class="btn ghost wide" onclick="MiCampo.wizard('pieces')">Atrás</button></div>`,7,9)}
function openingName(v){return OPENING_STYLES[v]?.label||v}
function familyPaletteHTML(s){if(s.type!=='family')return '';const keys=s.familyStructure==='adoptive'?['adoptive','current','symbolic']:s.familyStructure==='origin'?['origin','maternal','paternal','intuitive','symbolic']:s.familyStructure==='both'?['adoptive','origin','intuitive','symbolic']:s.familyStructure==='intuitive'?['intuitive','origin','maternal','paternal','symbolic']:s.familyStructure==='chosen'?['chosen','current','symbolic']:['nuclear','maternal','paternal','current','adoptive','origin','intuitive','chosen','symbolic'];const labels=[...new Set(keys.flatMap(k=>FAMILY_GROUPS[k]||[]))];return `<section class="family-palette"><div class="section-title"><h3>Añadir familiares o vínculos</h3></div><div class="family-chips">${labels.map(label=>{const on=s.pieces.some(p=>p.label===label);return `<button class="family-chip ${on?'selected':''}" onclick="MiCampo.toggleFamilyRep('${escAttr(label)}')">${on?'✓ ':''}${esc(label)}</button>`}).join('')}</div></section>`}
function intuitiveSetupHTML(s){if(!isIntuitiveSession(s))return '';const count=s.pieces.filter(p=>p.hypothetical).length;const cfg=intuitiveOptionsForType(s.type);return `<section class="card intuition-card compact"><div class="section-title"><div><div class="eyebrow">Intuición activa</div><h3>${esc(cfg.heading)}</h3></div><span class="badge personal">${count} figura${count===1?'':'s'}</span></div><p class="note">${esc(cfg.note)}</p><div class="secondary-actions"><button class="btn secondary" onclick="MiCampo.openIntuitionGenerator()">✦ Añadir desde lo que siento</button><button class="btn ghost" onclick="MiCampo.generateIntuitiveSet()">◌ Generar 3 figuras simbólicas</button><button class="btn ghost" onclick="MiCampo.addIntuitiveRep('unknown')">＋ Figura sin nombre</button></div></section>`}
function repsStep(){const s=ensureActive();return wizardShell(`<section class="hero"><div class="eyebrow">Paso 8</div><h2>Representantes</h2><p class="lead">Edita nombres, agrega vínculos o retira lo que no quieras representar. Las figuras creadas por intuición siguen siendo completamente editables.</p></section>${intuitiveSetupHTML(s)}${familyPaletteHTML(s)}<div class="reps">${s.pieces.map((p,i)=>`<div class="rep-row ${p.hypothetical?'intuitive-rep':''}"><div class="rep-num">${i+1}</div><div class="rep-input-wrap"><input type="text" value="${esc(p.label)}" maxlength="70" oninput="MiCampo.renameRep('${p.id}',this.value)"/>${p.hypothetical?`<small class="rep-origin">✦ figura intuitiva · hipotética</small>`:''}</div><button class="rep-delete" aria-label="Eliminar" onclick="MiCampo.deleteRep('${p.id}')">×</button></div>`).join('')}</div><button class="btn secondary wide" onclick="MiCampo.addRep()">＋ Añadir representante personalizado</button><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.beginSession()">Comenzar apertura</button><button class="btn ghost wide" onclick="MiCampo.wizard('prepare')">Atrás</button></div>`,8,9)}

function sessionView(){const s=state.data.active;if(!s){state.route='home';return homeView()}
  if(s.stage==='opening')return openingView(s);if(s.stage==='placement')return placementView(s);if(s.stage==='observation')return observationView(s);if(s.stage==='movement')return movementView(s);if(s.stage==='phrase')return phraseView(s);if(s.stage==='closing')return closingView(s);if(s.stage==='integration')return integrationView(s);return openingView(s)}
function sessionChrome(s,inner,step,total){return shell(`<div class="session-head">${progress(stageLabel(s.stage),step,total)}<div class="pill-row"><span class="pill active">${esc(TYPE_DEFS[s.type]?.label||'Libre')}</span><span class="pill">${esc(s.depth)}</span></div></div>${state.settings.companion?`<button class="session-companion" onclick="MiCampo.companionPanel()" aria-label="Compañero de Campo"><div id="companion3d-session" class="companion3d small">${companionFallbackMarkup('session')}</div></button>`:''}${inner}`,{nav:false,pause:true,title:'Mi Campo'})}
function openingText(style){
  const map={neutral:'Durante los próximos minutos observa el tema con curiosidad. No necesitas encontrar una respuesta inmediata.',systemic:'Observa posiciones, distancias y vínculos dentro de esta representación. Deja que la disposición te sugiera preguntas.',spiritual:'Abre este espacio con intención y presencia. Puedes recibir cada imagen como un símbolo personal y dejar pasar lo que no te resuene.',energetic:'Nota qué zonas se sienten más intensas, ligeras, cercanas o distantes para ti. Usa esas sensaciones como lenguaje simbólico.',meditative:'Respira suavemente. Siente el apoyo del cuerpo y observa el espacio frente a ti. No necesitas apresurar ninguna respuesta.',custom:'Respira, observa el conjunto y presta atención tanto a los vínculos como a las sensaciones que despiertan en ti.'};return map[style]||map.neutral
}
function openingView(s){const hint=s?.exerciseProtocol?.openingHint;return sessionChrome(s,`<section class="card"><div class="eyebrow">Apertura</div><div class="breath" aria-hidden="true"></div><h2 style="text-align:center">Llega al espacio.</h2><p class="lead" style="text-align:center;margin-left:auto;margin-right:auto">Respira con normalidad. Nota el contacto del cuerpo con la silla o el suelo. Mira brevemente la mesa.</p>${hint?`<p class="subinstruction exercise-hint">${esc(hint)}</p>`:''}</section><div class="card soft"><div class="quote">${esc(openingText(s.openingStyle))}</div></div><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.openingDone()">Cuando estés preparado, continuar</button><button class="btn ghost wide" onclick="MiCampo.readCurrent()">🔊 Leer en voz alta</button></div>`,1,10)}

function placementView(s){const idx=s.placementIndex;const p=s.pieces[idx];const placed=s.pieces.filter(x=>x.placed).length;
  if(!p){return sessionChrome(s,`<section class="card"><h2>Campo colocado.</h2><p class="lead">Antes de interpretar, observa el conjunto durante unos segundos.</p></section><button class="btn primary wide" onclick="MiCampo.beginObservation('movement')">Observar</button>`,4,10)}
  if(state.placementMode==='physical')return sessionChrome(s,`<div class="eyebrow">Pieza ${idx+1} · ${esc(p.label)}</div><div class="instruction">Ahora toma una pieza que represente a <strong>${esc(p.label)}</strong>.</div><p class="subinstruction">${p.hypothetical?'No intentes identificar a una persona real. Nota dónde tu intuición quiere poner esta figura, qué distancia pide y hacia dónde parece querer mirar.':'Colócala espontáneamente sobre la mesa. No necesitas elegir su posición racionalmente.'}</p><div class="card soft"><p class="note">${p.hypothetical?'Esta pieza puede representar solamente una sensación, una presencia imaginada, una ausencia o un lugar vacío dentro de la historia que estás creando hoy.':'El teléfono no sustituye la colocación física. Cuando la pieza esté en la mesa, registra una aproximación en el mapa digital.'}</p></div><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.physicalPlaced()">Ya está colocada</button><button class="btn ghost wide" onclick="MiCampo.changePieceChoice()">Quiero cambiar la pieza</button><button class="btn ghost wide" onclick="MiCampo.readCurrent()">🔊 Repetir instrucción</button></div>`,2+placed,10)
  return sessionChrome(s,`<div class="eyebrow">Registrar posición · ${esc(p.label)}</div><div class="instruction">Arrastra la pieza digital a una posición aproximada.</div><p class="subinstruction">Después ajusta hacia dónde está orientada. No hace falta precisión milimétrica.</p>${boardHTML(s,p.id)}<div class="rotate-tools"><button class="btn small secondary" onclick="MiCampo.rotate(-15)">↺ 15°</button><div class="angle">${Math.round(p.rotation)}°</div><button class="btn small secondary" onclick="MiCampo.rotate(15)">15° ↻</button></div>${postureTools(p)}<div class="reading-actions"><button class="btn ghost small" onclick="MiCampo.interpretPiece('${p.id}')">Interpretar esta pieza</button></div>${renderInterpretationCard()}<div class="action-stack"><button class="btn primary wide" onclick="MiCampo.savePlacement()">Guardar posición</button><button class="btn ghost wide" onclick="MiCampo.placementPhysicalBack()">Volver</button></div>`,2+placed,10)}

function fieldLayerSVG(s,layer){const ps=s.pieces.filter(p=>p.placed);if(!ps.length||layer==='none')return '';const lines=[];const px=p=>p.x*100,py=p=>p.y*100;
  if(layer==='orientation')ps.forEach(p=>{const a=(p.rotation-90)*Math.PI/180;const x2=px(p)+Math.cos(a)*13,y2=py(p)+Math.sin(a)*13;lines.push(`<line x1="${px(p)}" y1="${py(p)}" x2="${x2}" y2="${y2}" class="layer-orientation"/>`)});
  if(layer==='distances'||layer==='groups'){for(let i=0;i<ps.length;i++)for(let j=i+1;j<ps.length;j++){const d=dist(ps[i],ps[j]);if((layer==='distances'&&d<.42)||(layer==='groups'&&d<.28))lines.push(`<line x1="${px(ps[i])}" y1="${py(ps[i])}" x2="${px(ps[j])}" y2="${py(ps[j])}" class="${layer==='groups'?'layer-group':'layer-distance'}"/>`)}}
  if(layer==='center')lines.push('<circle cx="50" cy="50" r="18" class="layer-center"/><circle cx="50" cy="50" r="36" class="layer-center outer"/>');
  if(layer==='changes'&&s.initialLayout){const init=new Map(s.initialLayout.map(x=>[x.id,x]));ps.forEach(p=>{const a=init.get(p.id);if(a&&Math.hypot(p.x-a.x,p.y-a.y)>.035)lines.push(`<line x1="${a.x*100}" y1="${a.y*100}" x2="${px(p)}" y2="${py(p)}" class="layer-change"/>`)})}
  return `<svg class="field-layer" viewBox="0 0 100 100" preserveAspectRatio="none">${lines.join('')}</svg>`}
function fieldLayerControls(){return `<div class="field-layer-controls" aria-label="Capas de lectura">${[['none','Limpio'],['orientation','Orientación'],['distances','Distancias'],['groups','Grupos'],['center','Centro'],['changes','Cambios']].map(([v,l])=>`<button class="pill ${state.fieldLayer===v?'active':''}" onclick="MiCampo.setFieldLayer('${v}')">${l}</button>`).join('')}</div>`}
function boardHTML(s,selectedId,editable=true,context='session'){const pieces=s.pieces.filter(p=>p.placed || p.id===selectedId);return `<div class="board-wrap"><div id="field-board" class="board" data-editable="${editable?'1':'0'}" data-context="${context}"><span class="board-label">Campo · vista superior</span>${fieldLayerSVG(s,state.fieldLayer)}${pieces.map(p=>`<div class="piece-node posture-${p.posture||'upright'} ${p.id===selectedId?'selected':''}" data-piece-id="${p.id}" style="left:${p.x*100}%;top:${p.y*100}%;transform:translate(-50%,-50%) rotate(${p.rotation}deg)"><div class="piece-disc"><span class="facing-mark">▲</span></div><div class="piece-name" style="transform:rotate(${-p.rotation}deg)">${esc(p.label)}</div></div>`).join('')}</div></div>`}
function postureTools(p){return `<div class="posture-tools"><button class="posture-btn ${p.posture==='upright'?'active':''}" onclick="MiCampo.setPosture('upright')">♙<span>De pie</span></button><button class="posture-btn ${p.posture==='lying'?'active':''}" onclick="MiCampo.setPosture('lying')">▬<span>Acostada</span></button><button class="posture-btn ${p.posture==='tilted'?'active':''}" onclick="MiCampo.setPosture('tilted')">◩<span>Inclinada</span></button></div>`}


function degNorm(v){return ((v%360)+360)%360}
function angleDiff(a,b){let d=Math.abs(degNorm(a)-degNorm(b));return Math.min(d,360-d)}
function angleToward(a,b){const dx=b.x-a.x,dy=b.y-a.y;return degNorm(Math.atan2(dy,dx)*180/Math.PI+90)}
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function centerDist(p){return Math.hypot(p.x-.5,p.y-.5)}
function placedPieces(s){return s.pieces.filter(p=>p.placed)}
function nearestTo(p,s){const others=placedPieces(s).filter(x=>x.id!==p.id).map(x=>({p:x,d:dist(p,x)})).sort((a,b)=>a.d-b.d);return others[0]||null}
function relationMeta(a,b){const d=dist(a,b);const aFaces=angleDiff(a.rotation,angleToward(a,b))<48;const bFaces=angleDiff(b.rotation,angleToward(b,a))<48;return {d,aFaces,bFaces}}
function posturePhrase(p){return ({upright:'aparece de pie, con una cualidad de presencia, disponibilidad o firmeza',lying:'aparece acostada, lo que podría evocar retirada, descanso, vulnerabilidad, agotamiento o menor disponibilidad',tilted:'aparece inclinada, lo que podría sugerir transición, ambivalencia, inestabilidad o búsqueda de apoyo'}[p.posture||'upright'])}
function locationPhrase(p){const c=centerDist(p);if(c<.18)return 'ocupa una zona central del campo, por lo que podría estar tomando protagonismo en esta escena';if(c>.53)return 'está cerca de la periferia, lo que podría evocar distancia, diferenciación, transición o una posición menos central';return 'se encuentra en una zona intermedia del campo'}
function readingRecord(title,text,mode,ids=[]){const ss=ensureActive();const r={id:uid('reading'),at:nowISO(),title,text,mode,ids};ss.symbolicReadings=ss.symbolicReadings||[];ss.symbolicReadings.push(r);state.interpretation=r;persist();render()}
function pieceReading(p,s,variant=0){const near=nearestTo(p,s);const intro=p.hypothetical?`Si tratamos a ${p.label} como una figura creada por tu intuición, puede encarnar provisionalmente un vacío, una presencia imaginada, una cualidad o un lugar de la historia que hoy necesitas representar; ${posturePhrase(p)} y ${locationPhrase(p)}.`:`Si tomamos a ${p.label} como una figura simbólica, ${posturePhrase(p)} y ${locationPhrase(p)}.`;const parts=[intro];if(near){const m=relationMeta(p,near.p);parts.push(m.d<.24?`Su cercanía con ${near.p.label} podría hablar de conexión, intensidad, alianza o poca distancia entre ambos elementos.`:m.d>.55?`La distancia respecto a ${near.p.label} podría representar autonomía, separación, desconexión o necesidad de espacio.`:`La relación espacial con ${near.p.label} se mantiene en una distancia intermedia, abierta a varias lecturas.`);if(m.aFaces)parts.push(`Además, ${p.label} está orientada hacia ${near.p.label}, lo que podría simbolizar atención, interés o disponibilidad para mirar ese vínculo.`)}if(variant%2)parts.push('Otra posibilidad es que esta posición describa más tu manera actual de percibir el vínculo que a la persona representada en sí.');return parts.join(' ')+themeContextSentence(s)}
function relationReading(a,b,variant=0){const m=relationMeta(a,b);const parts=[`Una posible lectura de ${a.label} y ${b.label}:`];parts.push(m.d<.24?'La cercanía entre ambas piezas podría evocar conexión, intensidad, alianza, dependencia o dificultad para diferenciarse.':m.d>.55?'La distancia podría evocar autonomía, desconexión, separación o una necesidad de espacio.':'La distancia intermedia podría representar un vínculo con espacio suficiente para observar tanto cercanía como autonomía.');if(m.aFaces&&m.bFaces)parts.push('Ambas se orientan mutuamente; esto podría simbolizar reconocimiento, diálogo, tensión o confrontación directa.');else if(m.aFaces&&!m.bFaces)parts.push(`${a.label} mira hacia ${b.label}, mientras ${b.label} dirige su orientación a otro lugar; podría representar una atención no simétrica o simplemente focos distintos.`);else if(!m.aFaces&&m.bFaces)parts.push(`${b.label} mira hacia ${a.label}, mientras ${a.label} dirige su orientación a otro punto; podría evocar una búsqueda de contacto no equivalente.`);else parts.push('Ninguna está orientada directamente hacia la otra; podría sugerir caminos paralelos, distancia, autonomía o algo que todavía no se mira de frente.');if(variant%2)parts.push('También puede leerse como una imagen del momento presente, sin necesidad de convertirla en una explicación del pasado.');return parts.join(' ')+themeContextSentence(ensureActive())}
function fieldReading(s,variant=0){const ps=placedPieces(s);if(ps.length<2)return 'Coloca al menos dos representantes para leer relaciones dentro del campo.';const intuitive=ps.filter(p=>p.hypothetical);const pairs=[];for(let i=0;i<ps.length;i++)for(let j=i+1;j<ps.length;j++)pairs.push({a:ps[i],b:ps[j],d:dist(ps[i],ps[j])});pairs.sort((x,y)=>x.d-y.d);const close=pairs[0],far=pairs[pairs.length-1];const central=[...ps].sort((a,b)=>centerDist(a)-centerDist(b))[0];const isolated=[...ps].sort((a,b)=>{const na=nearestTo(a,s)?.d||0,nb=nearestTo(b,s)?.d||0;return nb-na})[0];const parts=[`Una posible lectura del conjunto comienza por ${central.label}, que aparece como una figura relativamente central dentro de la escena.`];if(intuitive.length)parts.push(`En esta escena también aparecen ${intuitive.map(p=>p.label).join(', ')} como figuras nacidas de tu intuición. Podemos dejar que funcionen como personajes de una historia simbólica y observar qué sentido adquieren por su posición, sin necesitar saber a quién o a qué corresponderían fuera de esta sesión.`);if(close)parts.push(`${close.a.label} y ${close.b.label} forman la cercanía más marcada; esto podría representar un vínculo especialmente intenso, una alianza, una identificación o simplemente un foco de atención actual.`);if(far&&far.d>.5)parts.push(`${far.a.label} y ${far.b.label} están entre los elementos más separados, lo que podría evocar diferenciación, distancia o límites.`);if(isolated&&nearestTo(isolated,s)?.d>.38)parts.push(`${isolated.label} aparece relativamente aislada; una hipótesis sería independencia, retirada, poca conexión con el resto o necesidad de un lugar propio.`);const lying=ps.filter(p=>p.posture==='lying');if(lying.length)parts.push(`${lying.map(p=>p.label).join(', ')} ${lying.length>1?'aparecen':'aparece'} acostada${lying.length>1?'s':''}; dentro de esta metáfora podría hablar de descanso, vulnerabilidad, retirada o menor disponibilidad en la escena.`);if(variant%3===1)parts.push('Otra lectura posible es observar el campo como una fotografía de cómo se organizan hoy tus atenciones, más que como un relato fijo sobre la familia o la situación.');if(variant%3===2)parts.push('También puedes mirar qué pieza parece quedar como puente entre zonas del campo y qué cambiaría si únicamente modificas su orientación, sin moverla de lugar.');return parts.join(' ')+themeContextSentence(s)}
function intuitiveNarrativeReading(s,variant=0){
  const ps=placedPieces(s), intuitive=ps.filter(p=>p.hypothetical);if(!intuitive.length)return 'Añade y coloca al menos una figura intuitiva para construir un relato simbólico.';
  const yo=ps.find(p=>/^yo(?:\s|$)/i.test(p.label))||ps[0];const focus=[...intuitive].sort((a,b)=>centerDist(a)-centerDist(b))[0];const nearYo=yo&&focus?relationMeta(yo,focus):null;
  const felt=(s.responses||[]).filter(r=>r.question===INTUITIVE_OBS_QUESTIONS[2].q&&r.value&&r.value!=='No lo sé').slice(-1)[0]?.value;
  const stories=[
    `Como relato imaginario, ${focus.label} podría ocupar el papel de una presencia simbólica que no necesita identidad concreta: algo que tu intuición coloca aquí para representar una pregunta abierta, una cualidad, un vacío o una fuerza que todavía no tiene nombre.`,
    `Si esta escena fuera un cuento simbólico, ${focus.label} podría representar algo que llega hasta el presente no como un dato comprobable, sino como una imagen con la que explorar distancia, pertenencia, protección, deseo, tensión o curiosidad.`,
    `Otra historia posible sería pensar en ${focus.label} como un personaje compuesto: no necesariamente una persona histórica, sino una mezcla imaginada de aquello que sientes que pudo existir, faltar, proteger, drenar o sostener dentro de tu campo.`
  ];
  const parts=[stories[variant%stories.length]];
  if(nearYo){parts.push(nearYo.d<.24?`En tu disposición aparece muy cerca de ${yo.label}; dentro del relato podría sentirse como algo íntimo, presente o muy ligado a tu experiencia actual.`:nearYo.d>.55?`Está lejos de ${yo.label}; en la historia podría funcionar como una rama distante, una ausencia o algo que apenas comienza a hacerse visible.`:`Mantiene una distancia intermedia respecto a ${yo.label}, como si pudiera ser observado sin quedar completamente integrado ni completamente separado.`)}
  parts.push(`${posturePhrase(focus)[0].toUpperCase()+posturePhrase(focus).slice(1)}.`);
  if(felt)parts.push(`La palabra o sensación que registraste —“${felt}”— puede funcionar como el clima de esta historia. Puedes dejar que oriente la siguiente pregunta sin tomarla como información histórica.`);
  const rest=intuitive.filter(p=>p.id!==focus.id);if(rest.length)parts.push(`Las otras figuras intuitivas —${rest.map(p=>p.label).join(', ')}— pueden actuar como personajes secundarios, ramas, recursos o espacios vacíos. No necesitas decidir todavía qué “son”.`);
  return parts.join(' ')+themeContextSentence(s)
}
function compareReading(s){if(!s.initialLayout)return 'Todavía no existe una configuración inicial completa para comparar.';const init=new Map(s.initialLayout.map(x=>[x.id,x]));const changes=[];for(const p of placedPieces(s)){const a=init.get(p.id);if(!a)continue;const moved=Math.hypot(p.x-a.x,p.y-a.y);if(moved>.08)changes.push(`${p.label} cambió de lugar de forma visible`);if(angleDiff(p.rotation,a.rotation)>45)changes.push(`${p.label} cambió claramente de orientación`);if((p.posture||'upright')!==(a.posture||'upright'))changes.push(`${p.label} cambió de postura`)}const base=changes.length?`Entre el inicio y el momento actual destacan estos cambios: ${changes.join('; ')}. Como narrativa simbólica, pueden representar un reajuste de atención, distancia, disponibilidad o límites. Observa cuál de estos cambios te resulta más significativo.`:'La configuración actual permanece muy cerca de la inicial. Eso también puede ser significativo: quizá por ahora la escena pide observación más que movimiento.';return base+themeContextSentence(s)}
function renderInterpretationCard(){const r=state.interpretation;if(!r)return '';return `<section class="reading-card"><div class="reading-kicker">Lectura del campo</div><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p><div class="reading-buttons"><button class="btn primary small" onclick="MiCampo.deepenReading()">Profundizar</button><button class="btn ghost small" onclick="MiCampo.anotherReading()">Otra lectura</button><button class="btn ghost small" onclick="MiCampo.dismissReading()">No me resuena</button></div></section>`}

const OBS_QUESTIONS=[
  {q:'¿Qué pieza llama primero tu atención?',type:'piece'},
  {q:'¿Alguna parece demasiado cerca o demasiado lejos?',opts:['Sí, demasiado cerca','Sí, demasiado lejos','No especialmente','No lo sé']},
  {q:'¿Qué notas al mirar tu propia representación?',type:'text',ph:'Describe lo que notas ahora: tensión, calma, ganas de acercarte, distancia…'},
  {q:'¿Hay alguna pieza que espontáneamente quieras mover?',opts:['Sí','No','Tal vez','Prefiero no mover nada']}
];
const INTUITIVE_OBS_QUESTIONS=[
  {q:'Entre las figuras creadas por intuición, ¿cuál se siente más presente ahora?',type:'intuitive-piece'},
  {q:'Sin intentar explicar por qué, ¿qué cualidad notas alrededor de esa parte del campo?',opts:['Cercanía','Distancia','Protección','Tensión','Curiosidad','Vacío','No lo sé']},
  {q:'Si este vacío pudiera expresarse solo dentro de esta historia simbólica, ¿qué palabra, imagen o emoción te viene?',type:'text',ph:'Ej. frío, abrazo, silencio, fuerza, miedo, curiosidad, nada todavía…'},
  {q:'¿Qué pide tu intuición ahora?',opts:['Mover una pieza','Renombrar mentalmente una figura','Añadir significado después','Dejar todo como está','No lo sé']}
];
function observationQuestions(s){
  const custom=s?.exerciseProtocol?.observationQuestions;
  return Array.isArray(custom)&&custom.length?custom:(isIntuitiveSession(s)?INTUITIVE_OBS_QUESTIONS:OBS_QUESTIONS)
}
function observationView(s){const questions=observationQuestions(s);const item=questions[state.observationIndex];return sessionChrome(s,`<div class="eyebrow">Observación ${state.observationIndex+1} de ${questions.length}</div><div class="question">${item.q}</div><p class="subinstruction">${isIntuitiveSession(s)?'Deja que la respuesta aparezca como sensación, imagen o impulso; no necesitas convertirla en un dato literal.':'Observa primero y registra lo que llame tu atención.'}</p>${observationInput(item,s)}<button class="btn ghost wide" onclick="MiCampo.readCurrent()">🔊 Leer pregunta</button>`,5,10)}
function observationInput(item,s){if(item.type==='piece'||item.type==='intuitive-piece'){let choices=s.pieces.filter(p=>p.placed);if(item.type==='intuitive-piece'){const intuitive=choices.filter(p=>p.hypothetical);if(intuitive.length)choices=intuitive}return `<div class="response-grid">${choices.map(p=>`<button class="choice" onclick="MiCampo.answerObservation('${p.id}','${escAttr(p.label)}')"><span class="choice-icon">●</span><span><strong>${esc(p.label)}</strong><small>${p.hypothetical?'Figura intuitiva':'Es la que noto primero.'}</small></span></button>`).join('')}</div>`;}
  if(item.type==='text')return `<div class="field"><textarea id="obs-text" maxlength="800" placeholder="${esc(item.ph)}"></textarea></div><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.answerObservationText()">Registrar observación</button><button class="btn ghost wide" onclick="MiCampo.answerObservationText(true)">No sé / continuar</button></div>`;
  return `<div class="response-grid two">${item.opts.map(x=>`<button class="choice" onclick="MiCampo.answerObservation(null,'${escAttr(x)}')"><span><strong>${esc(x)}</strong></span></button>`).join('')}</div>`}
function escAttr(s){return String(s).replace(/\\/g,'\\\\').replace(/'/g,"\\'")}

function timelineHTML(s){const list=(s.layoutHistory||[]).filter(x=>x.layout?.length).slice(-8);if(!list.length)return '';return `<section class="timeline-card"><div class="section-title"><div><div class="eyebrow">Línea del campo</div><h3>Configuraciones</h3></div></div><div class="timeline-strip">${list.map((x,i)=>`<button onclick="MiCampo.restoreTimeline(${(s.layoutHistory||[]).indexOf(x)})"><span>${i+1}</span><small>${esc(x.label||x.kind||'Escena')}</small></button>`).join('')}</div></section>`}
function movementSuggestionsHTML(s){const list=s?.exerciseProtocol?.movementExperiments;if(!Array.isArray(list)||!list.length)return '';return `<section class="card soft"><div class="eyebrow">Experimentos sugeridos para esta constelación</div><div class="list">${list.slice(0,5).map((x,i)=>`<button class="choice" onclick="MiCampo.tryMovementSuggestion(${i})"><span class="choice-icon">↗</span><span><strong>${esc(typeof x==='string'?x:x.label||'Probar movimiento')}</strong>${x?.when?`<small>${esc(x.when)}</small>`:''}</span></button>`).join('')}</div><p class="note">Son propuestas reversibles. También puedes ignorarlas y mover cualquier pieza por intuición.</p></section>`}
function movementView(s){
  if(state.movementMode==='offer')return sessionChrome(s,`<div class="eyebrow">Explora el campo</div><div class="instruction">¿Quieres probar un pequeño movimiento?</div><p class="subinstruction">También puedes pedir una lectura simbólica antes de mover nada.</p>${movementSuggestionsHTML(s)}<div class="action-stack"><button class="btn primary wide" onclick="MiCampo.movementStart()">Sí, probar un movimiento</button><button class="btn secondary wide" onclick="MiCampo.interpretField()">✦ Interpretar el campo</button>${isIntuitiveSession(s)?`<button class="btn ghost wide" onclick="MiCampo.intuitiveNarrative()">◌ Crear relato intuitivo</button>`:''}${renderInterpretationCard()}<button class="btn ghost wide" onclick="MiCampo.skipMovement()">Continuar sin mover</button></div>`,6,10);
  if(state.movementMode==='edit'){const selected=s.pieces.find(p=>p.id===state.selectedPieceId)||s.pieces[0];return sessionChrome(s,`<div class="eyebrow">Movimiento simbólico</div><div class="instruction">Mueve una pieza si quieres explorar otra configuración.</div><p class="subinstruction">Puedes cambiar distancia, orientación o postura y luego comparar.</p><div class="pill-row">${s.pieces.map(p=>`<button class="pill ${p.id===selected.id?'active':''}" onclick="MiCampo.selectPiece('${p.id}')">${esc(p.label)}</button>`).join('')}</div>${boardHTML(s,selected.id)}${fieldLayerControls()}${timelineHTML(s)}<div class="rotate-tools"><button class="btn small secondary" onclick="MiCampo.rotate(-15)">↺ 15°</button><div class="angle">${Math.round(selected.rotation)}°</div><button class="btn small secondary" onclick="MiCampo.rotate(15)">15° ↻</button></div>${postureTools(selected)}<div class="reading-actions three"><button class="btn ghost small" onclick="MiCampo.interpretPiece('${selected.id}')">Esta pieza</button><button class="btn ghost small" onclick="MiCampo.openRelation('${selected.id}')">Esta relación</button><button class="btn ghost small" onclick="MiCampo.interpretField()">Todo el campo</button></div>${isIntuitiveSession(s)?`<button class="btn ghost wide" onclick="MiCampo.intuitiveNarrative()">◌ Relato intuitivo</button>`:''}${renderInterpretationCard()}<div class="secondary-actions"><button class="btn ghost" onclick="MiCampo.undoMovement(true)">Deshacer</button><button class="btn ghost" onclick="MiCampo.compareInitialReading()">Comparar con inicio</button></div><button class="btn primary wide" onclick="MiCampo.compareMovement()">Observar cómo se siente ahora</button>`,6,10)}
  if(state.movementMode==='compare')return sessionChrome(s,`<div class="eyebrow">Comparación</div><div class="question">¿Cómo se siente ahora esta configuración?</div><div class="response-grid two">${['Mejor','Igual','Más incómodo','Diferente','No lo sé'].map(x=>`<button class="choice" onclick="MiCampo.movementFeeling('${escAttr(x)}')"><span><strong>${x}</strong></span></button>`).join('')}</div>`,6,10);
  if(state.movementMode==='worse')return sessionChrome(s,`<div class="eyebrow">Puedes volver atrás</div><div class="instruction">El cambio resultó más incómodo.</div><p class="subinstruction">Puedes regresar a la posición anterior o conservarla para observar un momento.</p><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.undoMovement()">Volver a la posición anterior</button><button class="btn ghost wide" onclick="MiCampo.finishMovement()">Conservar y continuar</button></div>`,6,10);
  return sessionChrome(s,`<div class="instruction">Observa unos segundos antes de otro cambio.</div><p class="subinstruction">¿Hay algo concreto que notes ahora?</p>${renderInterpretationCard()}<div class="action-stack"><button class="btn primary wide" onclick="MiCampo.finishMovement()">Continuar</button><button class="btn ghost wide" onclick="MiCampo.movementAgain()">Probar otro movimiento</button><button class="btn ghost wide" onclick="MiCampo.interpretField()">Otra lectura del campo</button></div>`,6,10)
}

function phraseView(s){const phrase=choosePhrase(s);return sessionChrome(s,`<div class="eyebrow">Frase simbólica opcional</div><div class="instruction">Prueba mentalmente esta frase y observa cómo te resulta.</div><div class="card"><div class="quote">“${esc(phrase)}”</div></div><div class="response-grid two">${['Me da calma','Me incomoda','No siento nada','No me representa'].map(x=>`<button class="choice" onclick="MiCampo.phraseFeeling('${escAttr(x)}')"><span><strong>${x}</strong></span></button>`).join('')}</div><div class="secondary-actions"><button class="btn ghost" onclick="MiCampo.nextPhrase()">Probar otra</button><button class="btn ghost" onclick="MiCampo.customPhrase()">Modificarla</button></div><button class="btn primary wide" onclick="MiCampo.skipPhrase()">Continuar al cierre</button>`,7,10)}

function closingView(s){const defaultSteps=[
  {title:'Mira la configuración final.',text:'Observa el conjunto sin cambiar nada durante unos segundos.',button:'Ya la observé'},
  {title:'¿Hay un pequeño ajuste que quieras hacer?',text:'Si no lo hay, no es necesario mover nada.',button:'Continuar'},
  {title:'Mira tu propia representación.',text:'Nota su orientación, distancia y tu reacción actual, sin convertirla en una conclusión definitiva.',button:'Continuar'},
  {title:'Por ahora puedo dejar esta imagen aquí y continuar con mi día.',text:'Puedes probar la frase o simplemente dejarla pasar.',button:'Retirar las piezas'},
  {title:'Retira lentamente las piezas una por una.',text:'Estas piezas han servido como representación simbólica. Puedes dejarlas ahora y volver al espacio que te rodea.',button:'Volver al entorno'}
];const custom=s?.exerciseProtocol?.closingSteps;const steps=Array.isArray(custom)&&custom.length?[...custom.map((x,i)=>({title:x.title,text:x.text||'',button:i===custom.length-1?'Volver al entorno':'Continuar'})),{title:'Retira lentamente las piezas una por una.',text:s?.exerciseProtocol?.closingPrompt||'Deja la representación y vuelve al espacio que te rodea.',button:'Volver al entorno'}]:defaultSteps;const st=steps[state.closeStep]||steps[steps.length-1];return sessionChrome(s,`<div class="eyebrow">Cierre ${Math.min(state.closeStep+1,steps.length)} de ${steps.length}</div><div class="instruction">${esc(st.title)}</div><p class="subinstruction">${esc(st.text)}</p>${state.closeStep===0?`${boardHTML(s,null,false)}<label class="btn ghost wide" style="margin-top:8px">📷 Fotografiar posición final<input class="hidden" type="file" accept="image/*" capture="environment" onchange="MiCampo.savePhoto(this,'final')"></label>`:''}<div class="action-stack"><button class="btn primary wide" onclick="MiCampo.closeNext()">${esc(st.button)}</button>${state.closeStep===1?`<button class="btn ghost wide" onclick="MiCampo.returnToMovement()">Hacer un ajuste</button>`:''}</div>`,8,10)}

const INTEGRATIONS=[['Escribir una frase','✎'],['Beber agua conscientemente','◌'],['Caminar 5 minutos','↗'],['Dibujar la configuración','◇'],['Elegir una palabra','•'],['Respirar y descansar','≈'],['Contacto con naturaleza','❧']];
function integrationView(s){const custom=s?.exerciseProtocol?.integrationActivities;const integrations=Array.isArray(custom)&&custom.length?custom.map((x,i)=>[x,['✎','◌','↗','◇','•','≈','❧'][i%7]]):INTEGRATIONS;if(!s.integration.activity)return sessionChrome(s,`<div class="eyebrow">Integración</div><div class="instruction">Elige una actividad sencilla para cerrar.</div><p class="subinstruction">Una sola es suficiente.</p><div class="grid">${integrations.map(x=>`<button class="choice" onclick="MiCampo.chooseIntegration('${escAttr(x[0])}')"><span class="choice-icon">${x[1]}</span><span><strong>${esc(x[0])}</strong></span></button>`).join('')}</div>`,9,10);
  return sessionChrome(s,`<div class="eyebrow">Acción cotidiana</div><div class="instruction">Después de observar esta situación, ¿hay una acción pequeña y concreta que quieras realizar?</div><p class="subinstruction">Puede ser “ninguna por ahora”. La sesión no necesita producir una decisión.</p><div class="field"><textarea id="integration-action" maxlength="700" placeholder="Ej. Escribiré dos opciones concretas mañana…">${esc(s.integration.action)}</textarea></div><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.finishSession()">Guardar y ver resumen</button><button class="btn ghost wide" onclick="MiCampo.noAction()">Ninguna por ahora</button></div>`,9,10)}

function summaryView(s){return shell(`<section class="hero"><div class="eyebrow">Sesión guardada</div><h2>${esc(s.topic||'Exploración simbólica')}</h2><p class="lead">${esc(fmtDate(s.updatedAt))}</p></section>${summaryCards(s)}<div class="action-stack"><button class="btn secondary wide" onclick="MiCampo.saveSessionAsPractice('${escAttr(s.id)}')">✦ Guardar esta estructura como nueva práctica</button><button class="btn primary wide" onclick="MiCampo.go('home')">Volver a inicio</button><button class="btn ghost wide" onclick="MiCampo.go('history')">Abrir historial</button></div>`,{nav:true,title:'Resumen'})}
function summaryCards(s){return `<div class="card"><div class="eyebrow">Intención</div><p>${esc(s.intention)}</p></div><div class="card"><div class="eyebrow">Representantes</div><p>${s.pieces.map(p=>esc(p.label)).join(' · ')}</p>${s.pieces.some(p=>p.hypothetical)?`<p class="note">✦ Incluye figuras intuitivas creadas para explorar simbólicamente vacíos, sensaciones o presencias todavía sin nombre.</p>`:''}</div><div class="card"><div class="eyebrow">Cambios principales</div><p>${s.movements.length?`${s.movements.length} movimiento${s.movements.length>1?'s':''} registrado${s.movements.length>1?'s':''}.`:'No se registraron movimientos.'}</p><p class="note">${s.movements.map(m=>esc(m.feeling||'Movimiento observado')).join(' · ')}</p></div><div class="card"><div class="eyebrow">Frases probadas</div><p>${s.phrasesTested.length?s.phrasesTested.map(x=>`“${esc(x.phrase)}” — ${esc(x.feeling)}`).join('<br><br>'):'No se probó ninguna frase.'}</p></div><div class="card"><div class="eyebrow">Lecturas simbólicas</div><p>${s.symbolicReadings?.length?s.symbolicReadings.slice(-3).map(x=>esc(x.text)).join('<br><br>'):'No se solicitó una lectura del campo.'}</p></div><div class="card"><div class="eyebrow">Integración</div><p><strong>${esc(s.integration.activity||'Sin actividad')}</strong></p><p>${esc(s.integration.action||'Sin acción definida.')}</p></div>`}

function historyCard(s){return `<button class="list-item" style="width:100%;text-align:left;color:inherit" onclick="MiCampo.openHistory('${s.id}')"><div class="meta">${esc(fmtDate(s.updatedAt))} · ${esc(TYPE_DEFS[s.type]?.label||'Libre')}</div><strong>${esc(s.topic||'Sesión sin título')}</strong><span class="note">${esc(s.intention||'')}</span></button>`}
function historyView(){const sessions=state.data.sessions.slice().sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt));return shell(`<section class="hero"><div class="eyebrow">Diario privado</div><h2>Historial</h2><p class="lead">Tus sesiones se guardan en este navegador. No se envían automáticamente a un modelo.</p></section>${sessions.length?`<div class="list">${sessions.map(historyCard).join('')}</div>`:`<div class="empty"><h3>Aún no hay sesiones.</h3><p>Cuando cierres una constelación, aparecerá aquí.</p></div>`}<button class="btn ghost wide" onclick="MiCampo.exportData()">Exportar mis sesiones</button>`,{nav:true,title:'Historial'})}
function historyDetailView(){const s=state.data.sessions.find(x=>x.id===state.historySessionId);if(!s){state.route='history';return historyView()}return shell(`<button class="btn ghost small" onclick="MiCampo.go('history')">← Historial</button><section class="hero"><div class="eyebrow">${esc(TYPE_DEFS[s.type]?.label||'Libre')}</div><h2>${esc(s.topic)}</h2><p class="lead">${esc(fmtDate(s.updatedAt))}</p></section>${summaryCards(s)}${s.initialLayout?`<div class="card"><div class="eyebrow">Configuración final</div>${boardHTML(s,null,false)}</div>`:''}<div class="secondary-actions"><button class="btn secondary" onclick="MiCampo.duplicateSession('${s.id}')">Duplicar sesión</button><button class="btn secondary" onclick="MiCampo.saveSessionAsPractice('${s.id}')">Guardar como práctica</button><button class="btn danger" onclick="MiCampo.deleteHistory('${s.id}')">Eliminar</button></div>`,{nav:false,title:'Detalle'})}

function uniqQuestionsFromSession(s){const seen=new Set(),out=[];for(const r of s?.responses||[]){const q=String(r?.question||'').trim();if(q&&!seen.has(q)){seen.add(q);out.push({q,type:'text',ph:'Describe lo que notas ahora.'})}}return out.slice(0,16)}
function allExercises(){normalizeData();const built=window.CampoExercises?.list?.()||[];const custom=(state.data.customPractices||[]).map(x=>window.CampoConstellationFactory?.normalizePlan?.(x)||x);return [...custom,...built]}
function isCustomExercise(id){normalizeData();return state.data.customPractices.some(x=>x.id===id)}

function practiceStudioView(){
  const d=state.factoryDraft;
  const repText=d?.representatives?.join('\n')||'';
  const movementCount=d?.protocol?.movementExperiments?.length||0;
  const questionCount=d?.protocol?.observationQuestions?.length||0;
  return shell(`<section class="hero"><div class="eyebrow">Generador abierto</div><h2>Crea una constelación completa para cualquier tema.</h2><p class="lead">Las 12 prácticas iniciales son sólo semillas. Aquí puedes generar nuevas estructuras sin un catálogo cerrado, guardarlas como prácticas reutilizables o iniciar una sola vez.</p></section><div class="card"><div class="field"><label>¿Qué quieres constelar?</label><textarea id="factory-topic" maxlength="900" oninput="MiCampo.factoryTopic(this.value)" placeholder="Ej. Quiero explorar por qué me cuesta avanzar con este proyecto y qué papel tienen el miedo, mi familia, el dinero y mi próximo paso.">${esc(state.factoryTopic)}</textarea></div><div class="grid two"><div class="field"><label>Modalidad</label><select onchange="MiCampo.factoryType(this.value)"><option value="auto" ${state.factoryType==='auto'?'selected':''}>Automática</option>${Object.entries(TYPE_DEFS).map(([k,v])=>`<option value="${k}" ${state.factoryType===k?'selected':''}>${esc(v.label)}</option>`).join('')}</select></div><div class="field"><label>Profundidad</label><select onchange="MiCampo.factoryDepth(this.value)">${[['suave','Suave'],['normal','Normal'],['profunda','Profunda']].map(x=>`<option value="${x[0]}" ${state.factoryDepth===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div></div><div class="secondary-actions"><button class="btn secondary" onclick="MiCampo.generatePracticeLocal()">✦ Crear ahora en el dispositivo</button><button class="btn primary" onclick="MiCampo.generatePracticeGemini()" ${state.factoryBusy?'disabled':''}>${state.factoryBusy?'Generando…':'✦ Crear con Gemini'}</button></div><p class="note">El generador local funciona sin red. Gemini puede proponer una estructura más específica, pero el resultado siempre pasa por el mismo validador antes de entrar al motor de Campo.</p></div>${d?`<section class="card"><div class="section-title"><div><div class="eyebrow">Constelación generada</div><h3>${esc(d.title)}</h3></div><span class="badge personal">${esc(d.type)}</span></div><p class="note">${esc(d.description)}</p><div class="field"><label>Título editable</label><input value="${esc(d.title)}" maxlength="120" oninput="MiCampo.factorySetTitle(this.value)"></div><div class="field"><label>Representantes · uno por línea</label><textarea rows="9" maxlength="2400" oninput="MiCampo.factorySetRepresentatives(this.value)">${esc(repText)}</textarea></div><div class="chips"><span class="chip">${questionCount} preguntas</span><span class="chip">${movementCount} experimentos</span><span class="chip">${esc(d.minutes)} min</span><span class="chip">${esc(d.intensity)}</span></div><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.startFactoryPlan()">Iniciar esta constelación</button><button class="btn secondary wide" onclick="MiCampo.saveFactoryPractice()">Guardar como práctica reutilizable</button><button class="btn ghost wide" onclick="MiCampo.clearFactoryDraft()">Descartar borrador</button></div></section>`:''}<button class="btn ghost wide" onclick="MiCampo.go('library')">Volver a Prácticas</button>`,{nav:false,title:'Generador'});
}

function libraryView(){
  const exercises=allExercises();
  const exerciseCards=exercises.length?`<section class="hero compact"><div class="eyebrow">Prácticas abiertas</div><h2>Presets, prácticas creadas por ti y constelaciones generadas.</h2><p class="lead">No existe un límite de 12 prácticas. Puedes crear tantas definiciones como permita el almacenamiento del dispositivo; cada una usa el mismo motor completo de Campo.</p></section><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.go('practiceStudio')">✦ Generar una constelación completa</button><button class="btn secondary wide" onclick="MiCampo.go('builder')">＋ Constructor manual</button></div><div class="grid exercise-grid">${exercises.map(x=>`<article class="card exercise-card"><div class="exercise-meta"><span class="badge personal">${esc((x.category||'libre').toUpperCase())}</span><span class="exercise-time">${esc(x.minutes)} min · ${esc(x.intensity)}</span></div><h3>${esc(x.title)}</h3><p class="note">${esc(x.description)}</p><div class="chips">${(x.representatives||[]).slice(0,5).map(r=>`<span class="chip">${esc(r)}</span>`).join('')}${(x.representatives||[]).length>5?`<span class="chip">+${(x.representatives||[]).length-5}</span>`:''}</div><button class="btn secondary wide" onclick="MiCampo.startExercise('${escAttr(x.id)}')">Usar esta práctica</button>${isCustomExercise(x.id)?`<div class="secondary-actions"><button class="btn ghost small" onclick="MiCampo.editPractice('${escAttr(x.id)}')">Editar</button><button class="btn ghost small" onclick="MiCampo.duplicatePractice('${escAttr(x.id)}')">Duplicar</button><button class="btn danger small" onclick="MiCampo.deletePractice('${escAttr(x.id)}')">Eliminar</button></div>`:''}</article>`).join('')}</div>`:'';
  return shell(`<section class="hero"><div class="eyebrow">Prácticas y biblioteca</div><h2>Un motor, infinitas estructuras.</h2><p class="lead">Las prácticas iniciales sirven de ejemplo. El generador puede construir nuevas constelaciones completas para temas familiares, individuales, decisiones, relaciones, proyectos, energéticas o libres.</p></section>${exerciseCards}<section class="hero compact"><div class="eyebrow">Biblioteca</div><h2>Marco de uso</h2></section><div class="list">${LIBRARY.map(x=>`<article class="card"><span class="badge ${x.tag}">${x.tag==='theory'?'MARCO TEÓRICO':x.tag==='evidence'?'EVIDENCIA / LÍMITES':'OBSERVACIÓN PERSONAL'}</span><h3 style="margin-top:10px">${esc(x.title)}</h3><p class="note" style="font-size:.93rem">${esc(x.text)}</p></article>`).join('')}</div>`,{nav:true,title:'Prácticas'});
}

function genogramView(){normalizeData();const nodes=state.data.genogram.nodes;const gens=[-2,-1,0,1];const generationLabel=g=>({[-2]:'Abuelos / generación anterior',[-1]:'Padres / cuidadores',[0]:'Mi generación',[1]:'Hijos / siguiente generación'}[g]||'Otra generación');return shell(`<section class="hero"><div class="eyebrow">Mapa familiar</div><h2>Genograma simbólico editable</h2><p class="lead">Organiza personas conocidas, adoptivas, de origen, elegidas o figuras desconocidas. Después puedes llevar una selección directamente al campo.</p></section><div class="secondary-actions"><button class="btn secondary" onclick="MiCampo.openGenogramAdd()">＋ Añadir persona o figura</button><button class="btn ghost" onclick="MiCampo.genogramSelectAll()">Seleccionar todo</button></div><div class="genogram-board">${gens.map(g=>{const group=nodes.filter(n=>Number(n.generation)===g);return `<section class="gen-row"><div class="gen-label">${generationLabel(g)}</div><div class="gen-nodes">${group.length?group.map(n=>`<button class="gen-node branch-${esc(n.branch||'unknown')} ${state.genogramSelection.includes(n.id)?'selected':''}" onclick="MiCampo.toggleGenogram('${n.id}')"><span>${n.branch==='unknown'?'◌':'●'}</span><strong>${esc(n.label)}</strong><small>${esc(n.relation||n.branch||'')}</small>${n.id!=='geno_self'?`<em onclick="event.stopPropagation();MiCampo.deleteGenogramNode('${n.id}')">×</em>`:''}</button>`).join(''):'<p class="note">Sin figuras todavía.</p>'}</div></section>`}).join('')}</div><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.startFromGenogram()">Constelar selección</button><button class="btn ghost wide" onclick="MiCampo.go('home')">Volver</button></div>`,{nav:false,title:'Mapa familiar'})}
function builderSuggestions(topic){const t=(topic||'').toLowerCase();if(/adicci|consumo|compulsi/.test(t))return ['Yo','Adicción / consumo','Impulso','Necesidad','Consecuencia','Límite','Recurso'];if(/bruj|energ|mal de ojo|carga|presencia/.test(t))return ['Yo','Influencia percibida','Lo que siento','Miedo / impacto','Protección','Límite','Recurso'];if(/mam|pap|famil|ancestro|abuelo/.test(t))return ['Yo','Mi familia','Vínculo principal','Lo desconocido','Límite','Recurso'];if(/pareja|relaci|v[ií]nculo/.test(t))return ['Yo','Otra persona','El vínculo','Necesidad','Límite','Recurso'];return ['Yo','Tema','Lo que me detiene','Lo que necesito','Recurso']}
function builderView(){return shell(`<section class="hero"><div class="eyebrow">Constructor</div><h2>Crea una constelación desde cero.</h2><p class="lead">Escribe el tema y agrega representantes. Campo también puede proponer una estructura local por palabras clave.</p></section><div class="card"><div class="field"><label>Tema</label><textarea id="builder-topic" maxlength="500" oninput="MiCampo.builderTopic(this.value)" placeholder="Ej. Quiero explorar una sensación de bloqueo, una presencia externa y mi necesidad de protección">${esc(state.builderTopic)}</textarea></div><div class="secondary-actions"><button class="btn secondary" onclick="MiCampo.generateBuilder()">✦ Generar estructura simbólica</button><button class="btn ghost" onclick="MiCampo.clearBuilder()">Limpiar</button></div></div><section class="card"><div class="section-title"><h3>Representantes</h3><span class="badge personal">${state.builderReps.length}</span></div><div class="builder-chips">${state.builderReps.map((r,i)=>`<button class="builder-chip" onclick="MiCampo.removeBuilderRep(${i})">${esc(r)} <span>×</span></button>`).join('')}</div><div class="field compact"><label>Añadir representante</label><div class="inline-add"><input id="builder-rep" maxlength="70" placeholder="Ej. Mi miedo"><button class="btn small secondary" onclick="MiCampo.addBuilderRep()">Añadir</button></div></div></section><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.startBuilderSession()">Crear constelación</button><button class="btn ghost wide" onclick="MiCampo.go('home')">Volver</button></div>`,{nav:false,title:'Constructor'})}
function labView(){normalizeData();const s=state.data.lab;const selected=s.pieces.find(p=>p.id===state.selectedPieceId)||s.pieces[0];return shell(`<section class="hero"><div class="eyebrow">Laboratorio del Campo</div><h2>Experimenta sin iniciar una sesión.</h2><p class="lead">Coloca, gira y cambia posturas libremente. Puedes pedir una lectura simbólica del conjunto en cualquier momento.</p></section><div class="pill-row">${s.pieces.map(p=>`<button class="pill ${p.id===selected?.id?'active':''}" onclick="MiCampo.labSelect('${p.id}')">${esc(p.label)}</button>`).join('')}</div>${boardHTML(s,selected?.id,true,'lab')}${fieldLayerControls()}${selected?`<div class="rotate-tools"><button class="btn small secondary" onclick="MiCampo.labRotate(-15)">↺ 15°</button><div class="angle">${Math.round(selected.rotation)}°</div><button class="btn small secondary" onclick="MiCampo.labRotate(15)">15° ↻</button></div><div class="posture-tools"><button class="posture-btn ${selected.posture==='upright'?'active':''}" onclick="MiCampo.labPosture('upright')">♙<span>De pie</span></button><button class="posture-btn ${selected.posture==='lying'?'active':''}" onclick="MiCampo.labPosture('lying')">▬<span>Acostada</span></button><button class="posture-btn ${selected.posture==='tilted'?'active':''}" onclick="MiCampo.labPosture('tilted')">◩<span>Inclinada</span></button></div>`:''}<div class="secondary-actions"><button class="btn secondary" onclick="MiCampo.openLabAdd()">＋ Pieza</button><button class="btn ghost" onclick="MiCampo.labInterpret()">✦ Interpretar</button><button class="btn ghost" onclick="MiCampo.resetLab()">Reiniciar</button></div>${state.labReading?`<section class="reading-card"><div class="reading-kicker">Lectura libre</div><p>${esc(state.labReading)}</p></section>`:''}<button class="btn ghost wide" onclick="MiCampo.go('home')">Volver al Inicio</button>`,{nav:false,title:'Laboratorio'})}
function settingsView(){const s=state.settings;const lock=SecureStore.lockedEnabled();return shell(`<section class="hero"><div class="eyebrow">Personalización</div><h2>Ajustes</h2></section><div class="settings-group"><h3>Mundos visuales, movimiento y apariencia</h3><div class="card world-settings-card"><div class="section-title"><div><div class="eyebrow">Mundo activo</div><h3>${esc(visualWorld().label)}</h3></div><button class="btn secondary small" onclick="MiCampo.openWorlds()">Cambiar mundo</button></div><div class="world-mini-grid">${Object.entries(VISUAL_WORLDS).map(([k,w])=>`<button class="world-mini world-${k} ${s.visualWorld===k?'selected':''}" onclick="MiCampo.setVisualWorld('${k}')"><span>${w.icon}</span><strong>${w.label}</strong></button>`).join('')}</div><div class="field compact"><label>Apariencia general</label><select onchange="MiCampo.settingSelect('theme',this.value)"><option value="normal" ${s.theme==='normal'?'selected':''}>Clara</option><option value="dark" ${s.theme==='dark'?'selected':''}>Oscura</option></select></div><div class="field compact"><label>Movimiento del mundo</label><select onchange="MiCampo.setMotionStyle(this.value)">${Object.entries(MOTION_STYLES).map(([k,m])=>`<option value="${k}" ${s.motionStyle===k?'selected':''}>${m.label}</option>`).join('')}</select></div><div class="field compact"><label>Intensidad de navegación</label><select onchange="MiCampo.settingSelect('navigationMotion',this.value)"><option value="soft" ${s.navigationMotion==='soft'?'selected':''}>Suave</option><option value="expressive" ${s.navigationMotion==='expressive'?'selected':''}>Expresiva</option><option value="reduced" ${s.navigationMotion==='reduced'?'selected':''}>Reducida</option></select></div><div class="toggle-row"><div class="toggle-copy"><strong>Sincronizar sonido con el mundo</strong><small>Al cambiar de mundo, Campo selecciona automáticamente su paisaje sonoro.</small></div>${toggle('syncWorldSound',s.syncWorldSound)}</div><div class="toggle-row"><div class="toggle-copy"><strong>Animaciones</strong><small>Transiciones, órbitas, aparición de pantallas y respuesta táctil.</small></div>${toggle('animations',s.animations)}</div></div></div><div class="settings-group"><h3>Experiencia</h3><div class="card"><div class="toggle-row"><div class="toggle-copy"><strong>Acompañante 3D</strong><small>Axoflutter aparece en Inicio y se minimiza durante la sesión.</small></div>${toggle('companion',s.companion)}</div><div class="toggle-row"><div class="toggle-copy"><strong>Voz del acompañante</strong><small>Permite que Axoflutter lea instrucciones o mensajes cuando lo eliges como narrador.</small></div>${toggle('companionSpeaks',s.companionSpeaks)}</div><div class="field compact"><label>Presencia del acompañante</label><select onchange="MiCampo.settingSelect('companionPresence',this.value)"><option value="discreet" ${s.companionPresence==='discreet'?'selected':''}>Discreta</option><option value="normal" ${s.companionPresence==='normal'?'selected':''}>Normal</option><option value="present" ${s.companionPresence==='present'?'selected':''}>Presente</option></select></div><div class="field compact"><label>Calidad 3D</label><select onchange="MiCampo.settingSelect('companionQuality',this.value)"><option value="auto" ${s.companionQuality==='auto'?'selected':''}>Automática</option><option value="high" ${s.companionQuality==='high'?'selected':''}>Alta</option><option value="battery" ${s.companionQuality==='battery'?'selected':''}>Ahorro de batería</option></select></div><div class="toggle-row"><div class="toggle-copy"><strong>Memoria local de uso</strong><small>Recuerda temas, figuras frecuentes y lecturas descartadas solo en este dispositivo.</small></div>${toggle('memoryEnabled',s.memoryEnabled)}</div></div></div><div class="settings-group"><h3>Voz y sonido</h3><div class="card"><div class="toggle-row"><div class="toggle-copy"><strong>Lectura en voz alta</strong><small>Usa las voces instaladas en iOS/Safari.</small></div>${toggle('speech',s.speech)}</div><div class="toggle-row"><div class="toggle-copy"><strong>Narración automática</strong><small>Lee automáticamente la instrucción principal al cambiar de fase.</small></div>${toggle('autoNarration',s.autoNarration)}</div><div class="field compact"><label>Voz de la guía</label><select onchange="MiCampo.settingSelect('voiceURI',this.value)">${voiceOptions(s.voiceURI)}</select></div><div class="field compact"><label>Voz de Axoflutter</label><select onchange="MiCampo.settingSelect('companionVoiceURI',this.value)">${voiceOptions(s.companionVoiceURI)}</select></div><div class="secondary-actions"><button class="btn ghost" onclick="MiCampo.previewVoice('guide')">🔊 Probar guía</button><button class="btn ghost" onclick="MiCampo.previewVoice('companion')">🐉 Probar Axoflutter</button></div><div class="toggle-row"><div class="toggle-copy"><strong>Vibración</strong><small>Solo si el navegador la admite.</small></div>${toggle('vibration',s.vibration)}</div><div class="toggle-row"><div class="toggle-copy"><strong>Sonido ambiental</strong><small>Paisajes generativos creados localmente con Web Audio.</small></div>${toggle('ambient',s.ambient)}</div><div class="field compact"><label>Paisaje predeterminado</label><select onchange="MiCampo.settingSelect('ambientScene',this.value)">${['silence','water','forest','storm','deep'].map(v=>`<option value="${v}" ${s.ambientScene===v?'selected':''}>${soundscapeLabel(v)}</option>`).join('')}</select></div><div class="field compact"><label>Volumen ambiental</label><input type="range" min="0" max="1" step="0.05" value="${s.ambientVolume}" oninput="MiCampo.settingVolume(this.value)"></div><div class="field compact"><label>Velocidad de lectura</label><select onchange="MiCampo.settingSelect('instructionSpeed',this.value)"><option value="slow" ${s.instructionSpeed==='slow'?'selected':''}>Lenta</option><option value="normal" ${s.instructionSpeed==='normal'?'selected':''}>Normal</option><option value="fast" ${s.instructionSpeed==='fast'?'selected':''}>Rápida</option></select></div></div></div><div class="settings-group"><h3>Facilitador</h3><div class="card"><div class="field"><label>Estilo del facilitador</label><select onchange="MiCampo.settingSelect('facilitator',this.value)">${['neutral','systemic','meditative','spiritual','energetic','direct','deep'].map(v=>`<option value="${v}" ${s.facilitator===v?'selected':''}>${facName(v)}</option>`).join('')}</select></div></div></div><div class="settings-group"><h3>Privacidad y datos</h3><div class="card"><div class="section-title"><h3>Bloqueo local y cifrado</h3><span class="badge ${lock?'theory':'personal'}">${lock?'ACTIVO':'OPCIONAL'}</span></div><p class="note">Puedes cifrar localmente tema, historial y sesión activa con Web Crypto.</p>${lock?`<button class="btn danger wide" onclick="MiCampo.disableLock()">Desactivar bloqueo</button>`:`<button class="btn secondary wide" onclick="MiCampo.openLockSetup()">Crear código local</button>`}</div><div class="grid"><button class="btn ghost wide" onclick="MiCampo.exportCampo()">Exportar .campo</button><button class="btn ghost wide" onclick="MiCampo.openImportCampo()">Importar .campo</button></div><button class="btn ghost wide" onclick="MiCampo.go('privacy')">Privacidad y datos</button></div>`,{nav:true,title:'Ajustes'})}
function toggle(name,on){return `<label class="switch"><input type="checkbox" ${on?'checked':''} onchange="MiCampo.settingToggle('${name}',this.checked)"><span class="slider"></span></label>`}
function facName(v){return ({neutral:'Neutral',systemic:'Sistémico',meditative:'Meditativo',spiritual:'Espiritual',energetic:'Energético',direct:'Directo',deep:'Profundo',storm:'Tormenta estelar'}[v]||v)}

function privacyView(){return shell(`<section class="hero"><div class="eyebrow">Privacidad por defecto</div><h2>Qué queda aquí y qué sale del dispositivo.</h2></section><div class="card"><h3>Datos locales</h3><p class="note">Tema, intención, representantes, posiciones, respuestas, frases, movimientos, integración y configuración se guardan en el almacenamiento de este navegador. Las fotografías se guardan localmente en IndexedDB.</p></div><div class="card"><h3>Datos enviados a IA</h3><p class="note">En esta versión el Facilitador IA remoto está desactivado. Ningún historial se envía automáticamente a un modelo. El motor local puede completar una sesión sin IA.</p></div><div class="card"><h3>Bloqueo biométrico</h3><p class="note">Una web normal no puede invocar Face ID como un bloqueo nativo arbitrario sin una credencial WebAuthn configurada. Esta versión ofrece código local con cifrado; Face ID queda reservado para una futura envoltura nativa/Passkey compatible.</p></div><div class="grid"><button class="btn secondary wide" onclick="MiCampo.exportData()">Exportar mis sesiones</button><button class="btn danger wide" onclick="MiCampo.confirmDeleteAll()">Eliminar todos mis datos</button></div>`,{nav:true,title:'Privacidad'})}

function renderModal(){if(state.modal==='pause')return `<div class="modal-backdrop"><div class="modal"><div class="eyebrow">Pausa</div><h2>Detente donde estás.</h2><p class="lead">Mira tres objetos de tu entorno. Siente el contacto de los pies con el suelo. Respira con normalidad.</p><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.closeModal()">Continuar</button><button class="btn ghost wide" onclick="MiCampo.endFromPause()">Cerrar sesión</button><button class="btn danger wide" onclick="MiCampo.overwhelmed()">Estoy muy angustiado</button></div></div></div>`;
  if(state.modal==='active')return `<div class="modal-backdrop"><div class="modal"><h3>Sesión sin terminar</h3><p class="note">Puedes archivarla con un cierre breve o eliminarla.</p><div class="action-stack"><button class="btn secondary wide" onclick="MiCampo.archiveActive()">Cerrar y archivar</button><button class="btn danger wide" onclick="MiCampo.deleteActive()">Eliminar</button><button class="btn ghost wide" onclick="MiCampo.closeModal()">Cancelar</button></div></div></div>`;
  if(state.modal==='lockSetup')return `<div class="modal-backdrop"><div class="modal"><div class="eyebrow">Cifrado local</div><h3>Crea un código de 4 a 12 caracteres.</h3><div class="field"><label>Código</label><input id="pin1" type="password" inputmode="numeric" maxlength="12" autocomplete="new-password"></div><div class="field" style="margin-top:10px"><label>Repetir código</label><input id="pin2" type="password" inputmode="numeric" maxlength="12" autocomplete="new-password"></div><p class="note">Si olvidas este código, no podremos recuperar el contenido cifrado.</p><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.createLock()">Activar cifrado</button><button class="btn ghost wide" onclick="MiCampo.closeModal()">Cancelar</button></div></div></div>`;
  if(state.modal==='relationPick'){const s=ensureActive();const source=s.pieces.find(p=>p.id===state.relationSourceId);return `<div class="modal-backdrop"><div class="modal"><div class="eyebrow">Interpretar relación</div><h3>${source?esc(source.label):'Pieza'} ↔ ¿con quién?</h3><div class="list">${s.pieces.filter(p=>p.placed&&p.id!==state.relationSourceId).map(p=>`<button class="choice" onclick="MiCampo.interpretRelation('${p.id}')"><span class="choice-icon">●</span><span><strong>${esc(p.label)}</strong><small>Leer esta relación</small></span></button>`).join('')}</div><button class="btn ghost wide" onclick="MiCampo.closeModal()">Cancelar</button></div></div>`;}
  if(state.modal==='intuition'){const cfg=currentIntuitiveConfig();return `<div class="modal-backdrop"><div class="modal intuition-modal"><div class="eyebrow">Generador intuitivo</div><h2>${esc(cfg.modalTitle)}</h2><p class="note">${esc(cfg.modalNote)}</p><div class="intuition-choice-grid">${cfg.choices.map(x=>`<button class="choice" onclick="MiCampo.addIntuitiveRep('${x.id}')"><span><strong>${esc(x.label)}</strong><small>${esc(x.piece)}</small></span></button>`).join('')}</div><div class="field"><label>O nómbralo con tus propias palabras</label><input id="intuition-label" maxlength="90" placeholder="${esc(cfg.placeholder)}"></div><button class="btn secondary wide" onclick="MiCampo.addIntuitiveCustom()">Crear esta figura</button><button class="btn ghost wide" onclick="MiCampo.closeModal()">Cancelar</button></div></div>`;}
  if(state.modal==='notifications'){const active=state.data.active;const recent=state.data.sessions?.[0];return `<div class="modal-backdrop"><div class="modal"><div class="eyebrow">Novedades de Campo</div><h2>Tu espacio está al día.</h2><div class="list">${active?`<button class="choice" onclick="MiCampo.closeModal();MiCampo.resume()"><span><strong>Constelación abierta</strong><small>${esc(active.topic||'Exploración en curso')} · ${esc(stageLabel(active.stage))}</small></span></button>`:''}${recent?`<button class="choice" onclick="MiCampo.closeModal();MiCampo.openHistory('${recent.id}')"><span><strong>Última sesión guardada</strong><small>${esc(recent.topic||recent.template||'Sesión')}</small></span></button>`:''}<button class="choice" onclick="MiCampo.closeModal();MiCampo.go('practiceStudio')"><span><strong>Generador abierto</strong><small>Crea una constelación completa para cualquier tema.</small></span></button></div><button class="btn ghost wide" onclick="MiCampo.closeModal()">Cerrar</button></div></div>`;}
  if(state.modal==='companion')return `<div class="modal-backdrop"><div class="modal companion-modal"><div class="eyebrow">Guía Viva · Axoflutter</div><h2>¿Cómo te acompaño?</h2><button class="btn primary wide live-guide-btn" onclick="MiCampo.companionAction('live')">🎙️ Conversar en vivo con Gemini</button><p class="note" id="gemini-live-status">La conversación Live usa un token efímero; la clave GEMINI_API_KEY permanece en el servidor.</p><div class="grid two"><button class="choice" onclick="MiCampo.companionAction('speak')"><span><strong>🐉 Mensaje de Axoflutter</strong><small>Voz local rápida</small></span></button><button class="choice" onclick="MiCampo.companionAction('repeat')"><span><strong>🔊 Repetir instrucción</strong></span></button><button class="choice" onclick="MiCampo.companionAction('next')"><span><strong>✦ ¿Qué sigue?</strong></span></button><button class="choice" onclick="MiCampo.companionAction('interpret')"><span><strong>⌬ Interpretar el campo</strong></span></button><button class="choice" onclick="MiCampo.companionAction('pause')"><span><strong>Ⅱ Pausa</strong></span></button><button class="choice" onclick="MiCampo.companionAction('sound')"><span><strong>♫ Ambiente</strong><small>Activar o cambiar sonido</small></span></button></div><button class="btn ghost wide" onclick="MiCampo.companionAction('hide')">Ocultar acompañante</button><button class="btn ghost wide" onclick="MiCampo.closeModal()">Cerrar</button></div></div>`;
  if(state.modal==='genogramAdd')return `<div class="modal-backdrop"><div class="modal"><div class="eyebrow">Mapa familiar</div><h2>Añadir persona o figura</h2><div class="field"><label>Nombre o etiqueta</label><input id="geno-label" maxlength="70" placeholder="Ej. Abuela materna / Persona desconocida"></div><div class="field compact"><label>Relación</label><input id="geno-relation" maxlength="70" placeholder="Ej. abuela, cuidador, origen desconocido"></div><div class="field compact"><label>Rama</label><select id="geno-branch"><option value="maternal">Materna</option><option value="paternal">Paterna</option><option value="adoptive">Adoptiva / crianza</option><option value="origin">Origen</option><option value="chosen">Elegida</option><option value="current">Actual</option><option value="unknown">Desconocida / intuitiva</option></select></div><div class="field compact"><label>Generación</label><select id="geno-generation"><option value="-2">Abuelos / anterior</option><option value="-1">Padres / cuidadores</option><option value="0">Mi generación</option><option value="1">Hijos / siguiente</option></select></div><button class="btn primary wide" onclick="MiCampo.saveGenogramNode()">Añadir al mapa</button><button class="btn ghost wide" onclick="MiCampo.closeModal()">Cancelar</button></div></div>`;
  if(state.modal==='labAdd')return `<div class="modal-backdrop"><div class="modal"><div class="eyebrow">Laboratorio</div><h2>Nueva pieza</h2><div class="field"><label>Nombre</label><input id="lab-label" maxlength="70" placeholder="Ej. Una presencia / Mi miedo / Recurso"></div><div class="toggle-row"><div class="toggle-copy"><strong>Figura intuitiva</strong><small>Marca la pieza como símbolo surgido de la intuición.</small></div><label class="switch"><input id="lab-intuitive" type="checkbox"><span class="slider"></span></label></div><button class="btn primary wide" onclick="MiCampo.saveLabPiece()">Añadir pieza</button><button class="btn ghost wide" onclick="MiCampo.closeModal()">Cancelar</button></div></div>`;
  if(state.modal==='importCampo')return `<div class="modal-backdrop"><div class="modal"><div class="eyebrow">Importar</div><h2>Restaurar archivo .campo</h2><p class="note">Selecciona un archivo exportado por Mi Campo. Se valida su estructura antes de incorporarlo.</p><input id="campo-import" type="file" accept=".campo,application/json"><button class="btn primary wide" onclick="MiCampo.importCampo()">Importar archivo</button><button class="btn ghost wide" onclick="MiCampo.closeModal()">Cancelar</button></div></div>`;
  if(state.modal==='worlds'){const current=visualWorld();return `<div class="modal-backdrop"><div class="modal worlds-modal"><div class="eyebrow">Mundos de Campo</div><h2>Cambia la atmósfera completa.</h2><p class="lead">Cada mundo transforma colores, movimiento y —si lo deseas— el paisaje sonoro. Tu contenido y tus sesiones no cambian.</p><div class="world-picker">${Object.entries(VISUAL_WORLDS).map(([k,w])=>`<button class="world-card world-${k} ${state.settings.visualWorld===k?'selected':''}" onclick="MiCampo.setVisualWorld('${k}',true)"><span class="world-orb">${w.icon}</span><span><strong>${w.label}</strong><small>${w.desc}</small><em>♫ ${soundscapeLabel(w.sound)}</em></span></button>`).join('')}</div><div class="motion-picker"><div class="eyebrow">Movimiento</div>${Object.entries(MOTION_STYLES).map(([k,m])=>`<button class="motion-chip ${state.settings.motionStyle===k?'selected':''}" onclick="MiCampo.setMotionStyle('${k}')"><span>${m.icon}</span><strong>${m.label}</strong></button>`).join('')}</div><div class="secondary-actions"><button class="btn secondary" onclick="MiCampo.previewWorldSound()">♫ Escuchar este mundo</button><button class="btn ghost" onclick="MiCampo.closeModal()">Listo</button></div></div></div>`;}
  if(state.modal==='breath')return `<div class="modal-backdrop"><div class="modal breath-modal"><div class="eyebrow">Respirar</div><div class="breath-orb" aria-hidden="true"><span>✦</span></div><h2>Vuelve al centro.</h2><p class="lead">Inhala suavemente durante cuatro tiempos y exhala durante seis. Repite a tu ritmo.</p><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.closeModal()">Terminar práctica</button><button class="btn ghost wide" onclick="MiCampo.companionBreathVoice()">🔊 Guíame con voz</button></div></div></div>`;
  if(state.modal==='customPhrase')return `<div class="modal-backdrop"><div class="modal"><h3>Modifica la frase</h3><textarea id="custom-phrase" maxlength="500">${esc(choosePhrase(ensureActive()))}</textarea><button class="btn primary wide" style="margin-top:10px" onclick="MiCampo.saveCustomPhrase()">Probar esta versión</button><button class="btn ghost wide" style="margin-top:8px" onclick="MiCampo.closeModal()">Cancelar</button></div></div>`;
  return ''
}

function lockView(){return `<div class="app-shell" style="justify-content:center;padding-bottom:var(--safe-bottom)"><div class="card dark" style="margin:auto 0"><div class="brand-mark" style="margin-bottom:18px">${iconMark()}</div><div class="eyebrow" style="color:#d9b985">Mi Campo</div><h2>Contenido local cifrado.</h2><p class="muted">Introduce tu código para descifrar las sesiones en este dispositivo.</p><div class="field" style="margin-top:18px"><input id="unlock-pin" type="password" inputmode="numeric" maxlength="12" placeholder="Código" onkeydown="if(event.key==='Enter')MiCampo.unlock()"></div>${state.unlockError?`<p style="color:#f4b6ad">${esc(state.unlockError)}</p>`:''}<button class="btn primary wide" style="margin-top:12px" onclick="MiCampo.unlock()">Desbloquear</button><p class="note" style="color:rgba(255,255,255,.62)">El código se usa localmente; no se envía a un servidor.</p></div></div>`}

function crisisView(){return shell(`<section class="card dark"><div class="eyebrow" style="color:#e3c092">Salir del modo constelación</div><h2>Esta sesión se detiene aquí.</h2><p class="muted">Lo que escribiste sugiere que puede haber una situación de crisis o peligro inmediato. No voy a profundizar simbólicamente en eso.</p></section><div class="card"><h3>Busca apoyo humano ahora</h3><p class="note">Si existe peligro inmediato, contacta a los servicios de emergencia de tu zona o ve al servicio de urgencias más cercano. Si puedes, quédate acompañado y avisa a una persona de confianza.</p></div><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.crisisClose()">Cerrar y volver al inicio</button></div>`,{nav:false,title:'Seguridad'})}
function overwhelmView(){return shell(`<section class="hero"><div class="eyebrow">Regulación</div><h2>No hace falta seguir profundizando.</h2></section><div class="card"><p>Deja las piezas exactamente donde están. Mira tres objetos del entorno, nota dos sonidos y siente el contacto de los pies o la espalda. Respira con normalidad.</p><p class="note">Puedes cerrar la sesión sin obtener ninguna conclusión. Una reacción intensa no necesita interpretarse mediante la constelación.</p></div><div class="action-stack"><button class="btn primary wide" onclick="MiCampo.overwhelmClose()">Cerrar la sesión progresivamente</button><button class="btn ghost wide" onclick="MiCampo.goSession()">Volver solo si ya me siento estable</button></div>`,{nav:false,title:'Pausa'})}

function applyAppearance(){
  const theme=state.settings.theme==='normal'?'normal':'dark';
  const motion=!state.settings.animations?'reduced':(state.settings.navigationMotion||'expressive');
  const activeAtmosphere=(state.route==='session'||state.route==='new')?state.data.active:null;
  const requestedWorld=activeAtmosphere?.visualWorld||state.settings.visualWorld;
  const requestedMotion=activeAtmosphere?.motionStyle||state.settings.motionStyle;
  const world=normalizeVisualWorldKey(requestedWorld);
  const motionWorld=requestedMotion&&MOTION_STYLES[requestedMotion]?requestedMotion:'orbit';
  document.documentElement.dataset.theme=theme;
  document.documentElement.dataset.motion=motion;
  document.documentElement.dataset.world=world;
  document.documentElement.dataset.motionStyle=motionWorld;
  document.documentElement.style.colorScheme=theme==='dark'?'dark':'light';
  const meta=document.querySelector('meta[name="theme-color"]');if(meta){const colors={ocean:'#031d35',forest:'#071f1b',storm:'#070a24'};meta.content=colors[world]||'#080a2a'}
}

function render(){
  applyAppearance();
  document.body.dataset.route=state.route;
  if(state.locked){$app().innerHTML=lockView();return}
  let html='';
  if(state.route==='home')html=homeView();else if(state.route==='new')html=newView();else if(state.route==='session')html=sessionView();else if(state.route==='summary')html=summaryView(state.data.sessions.find(x=>x.id===state.historySessionId)||state.data.sessions[0]);else if(state.route==='history')html=historyView();else if(state.route==='historyDetail')html=historyDetailView();else if(state.route==='library')html=libraryView();else if(state.route==='settings')html=settingsView();else if(state.route==='privacy')html=privacyView();else if(state.route==='genogram')html=genogramView();else if(state.route==='builder')html=builderView();else if(state.route==='practiceStudio')html=practiceStudioView();else if(state.route==='lab')html=labView();else if(state.route==='crisis')html=crisisView();else if(state.route==='overwhelm')html=overwhelmView();else html=homeView();
  $app().innerHTML=html;
  requestAnimationFrame(()=>{bindBoard();window.CampoCompanion3D?.sync?.(state.route,state.settings,state.data.active);maybeAutoNarrate()});
  if(!state.settings.animations)document.documentElement.style.setProperty('--motion','0');
}

function maybeAutoNarrate(){if(!state.settings.autoNarration||state.route!=='session')return;const s=state.data.active;if(!s||s.voiceRole==='silent')return;const el=document.querySelector('.instruction,.question,.quote');const t=el?.textContent?.trim();if(!t)return;const key=[s.id,s.stage,state.observationIndex,state.placementIndex,state.movementMode,state.closeStep,t.slice(0,40)].join('|');if(key===state.lastAutoNarrationKey)return;state.lastAutoNarrationKey=key;speak(t,s.voiceRole==='companion'?'companion':'guide')}
function ensureActive(){if(!state.data.active)state.data.active=createSession();return state.data.active}
function bindBoard(){const board=document.getElementById('field-board');if(!board||board.dataset.editable!=='1')return;board.querySelectorAll('.piece-node').forEach(node=>{
  node.addEventListener('pointerdown',e=>{e.preventDefault();const id=node.dataset.pieceId;state.selectedPieceId=id;const s=board.dataset.context==='lab'?state.data.lab:ensureActive();const p=s?.pieces?.find(x=>x.id===id);if(!p)return;node.setPointerCapture?.(e.pointerId);
    const move=ev=>{const r=board.getBoundingClientRect();p.x=Math.max(.05,Math.min(.95,(ev.clientX-r.left)/r.width));p.y=Math.max(.05,Math.min(.95,(ev.clientY-r.top)/r.height));node.style.left=(p.x*100)+'%';node.style.top=(p.y*100)+'%'};
    const up=async()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);if(board.dataset.context==='lab'){state.data.lab.currentLayout=layoutSnapshot(state.data.lab);await SecureStore.saveData()}else await persist();render()};window.addEventListener('pointermove',move,{passive:false});window.addEventListener('pointerup',up,{once:true});
  })
})}

